(window.EX_CHUNKS=window.EX_CHUNKS||{})["b07"]={"诽谤":[["他因诽谤他人而被起诉。","ئۇ باشقىلارنى تۆھمەت قىلغانلىقى ئۈچۈن دەۋا قىلىندى.","u bashqilarni töhmet qilghanliqi üchün dewa qilindi."]],"钩子":[["他用钩子把箱子拉了过来。","ئۇ ئىلگىرىكى بىلەن ساندۇقنى تارتىپ كەلدى.","u ilgiriki bilen sanduqni tartip keldi."]],"公关":[["公司的公关部门处理了这次危机。","شىركەتنىڭ ئاممىۋى مۇناسىۋەت بۆلۈمى بۇ كرىزىسنى بىر تەرەپ قىلدى.","shirketning ammiwi munasiwet bölümi bu krizisni bir terep qildi."]],"僇":[["他因见义勇为而受到表彰，备受社会僇赏。","ئۇ ئادالەتپەرۋەرلىك قىلغانلىقى ئۈچۈن مۇكاپاتلىنىپ، جەمئىيەتنىڭ چوڭقۇر ھۆرمىتىگە ئېرىشتى.","u adaletperwerlik qilghanliqi üchün mukapatlinip, jem'iyetning chongqur hörmitige érishti."]],"咇":[["他“咇咇”地笑。","ئۇ «بىبى» دەپ كۈلدى.","u «bibi» dep küldi."]],"埇":[["埇城历史悠久，文化底蕴深厚。","يۇڭچېڭنىڭ تارىخى ئۇزۇن، مەدەنىيەت ئاساسى چوڭقۇر.","yungchéngning tarixi uzun, medeniyet asasi chongqur."]],"峇":[["峇山是东南亚的重要山脉。","باشەن جەنۇبىي شەرقىي ئاسىيادىكى مۇھىم تاغ تىزمىسى.","bashen jenubiy sherqiy asiyadiki muhim tagh tizmisi."]],"珇":[["这个字读作珇，不常见。","بۇ خەت «زۇ» دەپ ئوقۇلىدۇ، كۆپ ئۇچرىمايدۇ.","bu xet «zu» dep oqulidu, köp uchrimaydu."]],"禇":[["禇是古代祭祀时使用的器具。","چۇ قەدىمكى زاماندا قۇربانلىق مۇراسىمىدا ئىشلىتىلىدىغان سايمانلاردۇر.","chu qedimki zamanda qurbanliq murasimida ishlitilidighan saymanlardur."]],"荇":[["水面上漂浮着许多荇菜。","سۇ يۈزىدە نۇرغۇن سۇ ئۆسۈملۈكلىرى لەيلەپ تۇرىدۇ.","su yüzide nurghun su ösümlükliri leylep turidu."]],"蔇":[["蔇叶的形状像心形。","توققۇز يوپۇرماقنىڭ شەكلى يۈرەك شەكلىگە ئوخشايدۇ.","toqquz yopurmaqning shekli yürek sheklige oxshaydu."]],"藇":[["藇是植物的一种。","يۈ ئۆسۈملۈكنىڭ بىر تۈرى.","yü ösümlükning bir türi."]],"檇":[["檇树是一种观赏植物。","ئىنەك دەرىخى بىر خىل كۆرۈنمەسلىك ئۆسۈملۈكى.","inek derixi bir xil körünmeslik ösümlüki."]],"饇":[["这道饇菜味道不错。","بۇ قورۇما تائامنىڭ تەمى يامان ئەمەس.","bu qoruma taamning temi yaman emes."]],"髇":[["髇部活动受限。","ھەرىكەت چەكلىمىگە ئۇچرىغان.","heriket cheklimige uchrighan."]],"一中原则":[["一中原则是国际关系的重要准则。","بىر جۇڭگو پرىنسىپى خەلقئارا مۇناسىۋەتلەرنىڭ مۇھىم ئۆلچىمى.","bir junggo prinsipi xelq'ara munasiwetlerning muhim ölchimi."]],"騇":[["騇马的蹄子坚硬有力。","ئالا ئاتنىڭ تۇيىقى قاتتىق ۋە كۈچلۈك.","ala atning tuyiqi qattiq we küchlük."]],"一字巾":[["古代女子戴的‘一字巾’十分优雅。","قەدىمكى زاماندا ئاياللار كىيىدىغان «بىر خەتلىك رومال» ناھايىتى نەپىس ئىدى.","qedimki zamanda ayallar kiyidighan «bir xetlik romal» nahayiti nepis idi."]],"一箩筐":[["她买了一箩筐新鲜水果。","ئۇ بىر سېۋەت يېڭى مېۋە سېتىۋالدى.","u bir séwet yéngi méwe sétiwaldi."]],"一般贸易":[["他们从事一般贸易多年。","ئۇلار ئۇزۇن يىللاردىن بۇيان ئادەتتىكى سودا بىلەن شۇغۇللىنىپ كەلمەكتە.","ular uzun yillardin buyan adettiki soda bilen shughullinip kelmekte."]],"一见钟情":[["他对她一见钟情。","ئۇ ئۇنى كۆرگەن ھامان مېھىر-مۇھەببەت باغلىدى.","u uni körgen haman méhir-muhebbet baghlidi."]],"三田":[["三田是东京的一个区。","سانتەن توكيودىكى بىر رايون.","santen tokyodiki bir rayon."]],"不可磨灭":[["这段记忆永远不可磨灭。","بۇ ئەسلىمە مەڭگۈ ئۆچۈرگىلى بولمايدۇ.","bu eslime menggü öchürgili bolmaydu."]],"上睑":[["上睑下垂会影响视力。","ئۈستۈنكى قاپاق ساڭگىلىشى كۆرۈش قۇۋۋىتىگە تەسىر كۆرسىتىدۇ.","üstünki qapaq sanggilishi körüsh quwwitige tesir körsitidu."]],"不合体统":[["这种做法不合体统。","بۇ ئۇسۇل تەرتىپكە مۇۋاپىق ئەمەس.","bu usul tertipke muwapiq emes."]],"不好受":[["失败让他感到非常不好受。","مەغلۇبىيەت ئۇنى ئىنتايىن ئازابلىدى.","meghlubiyet uni intayin azablidi."]],"不怎么":[["他今天不怎么说话，显得很安静。","ئۇ بۈگۈن ئانچە كۆپ سۆزلىمەي، بىئارام كۆرۈنىدۇ.","u bügün anche köp sözlimey, biaram körünidu."]],"不惜一战":[["为了和平，不惜一战。","تىنچلىق ئۈچۈن، ئۇرۇشتىن يانماسلىق كېرەك.","tinchliq üchün, urushtin yanmasliq kérek."]],"不容置辩":[["事实如此，不容置辩，所有人都必须承认。","پاكىت شۇنداق، ئۇنىڭغا ئېنىقلىق بېرىشكە بولمايدۇ، ھەممە ئادەم ئېتىراپ قىلىشقا مەجبۇر.","pakit shundaq, uninggha éniqliq bérishke bolmaydu, hemme adem étirap qilishqa mejbur."]],"不相干":[["这件事与他不相干，别牵扯他。","بۇ ئىش ئۇنىڭغا ئالاقىسىز، ئۇنى ئارىلاشتۇرماڭ.","bu ish uninggha alaqisiz, uni arilashturmang."]],"世界大战":[["世界大战给人类带来了深重灾难。","دۇنيا ئۇرۇشى ئىنسانىيەتكە ئېغىر ئاپەت ئېلىپ كەلدى.","dunya urushi insaniyetke éghir apet élip keldi."]],"不当一回事":[["他完全不当一回事。","ئۇ بۇنى پۈتۈنلەي پەرۋا قىلمايدۇ.","u buni pütünley perwa qilmaydu."]],"不露声色":[["面对批评，他始终不露声色。","تەنقىدكە دۇچ كەلگەندە، ئۇ ھەرگىز ھېسسىياتىنى بىلدۈرمەيدۇ.","tenqidke duch kelgende, u hergiz héssiyatini bildürmeydu."]],"丙子胡乱":[["丙子胡乱时期社会动荡不安。","بىڭ زى قالايمىقانچىلىق دەۋرىدە جەمئىيەت تۇراقسىز ئىدى.","bing zi qalaymiqanchiliq dewride jem'iyet turaqsiz idi."]],"丫角":[["这个丫角的造型十分独特。","بۇ بۇرجەكنىڭ شەكلى ئىنتايىن ئالاھىدە.","bu burjekning shekli intayin alahide."]],"久假不归":[["他久假不归，让人十分担忧。","ئۇ ئۇزۇن ۋاقىت رۇخسەتسىز غايىب بولۇپ، كىشىلەرنى ئىنتايىن ئەنسىرەتتى.","u uzun waqit ruxsetsiz ghayib bolup, kishilerni intayin ensiretti."]],"事实婚":[["事实婚是指未登记但实际共同生活的婚姻。","پاكىتلىق نىكاھ تىزىملاتمىغان بىراق ئەمەلىيەتتە بىرگە ياشايدىغان نىكاھنى كۆرسىتىدۇ.","pakitliq nikah tizimlatmighan biraq emeliyette birge yashaydighan nikahni körsitidu."]],"事后聪明":[["事后聪明往往让人产生错觉。","ئاقىۋەت ئەقىللىق بولۇش كۆپىنچە كىشىلەردە خاتا تەسەۋۋۇر پەيدا قىلىدۇ.","aqiwet eqilliq bolush köpinche kishilerde xata tesewwur peyda qilidu."]],"二恶英":[["二恶英是一种对环境有害的污染物。","ئىككى ئوكسىن مۇھىتقا زىيانلىق بىر خىل بۇلغىغۇچىدۇر.","ikki oksin muhitqa ziyanliq bir xil bulghighuchidur."]],"二手车":[["他买了一辆价格便宜的二手车。","ئۇ باھاسى ئەرزان بىر ماشىنا سېتىۋالدۇق.","u bahasi erzan bir mashina sétiwalduq."]],"乳腺炎":[["乳腺炎会导致乳房红肿疼痛。","مەستىت سۈت بېزىنىڭ قىزىرىشى ۋە ئاغرىشىنى كەلتۈرۈپ چىقىرىدۇ.","mestit süt bézining qizirishi we aghrishini keltürüp chiqiridu."]],"乳酸菌":[["乳酸菌能改善肠道健康。","سۈت كىسلاتا باكتېرىيىلىرى ئۈچەي ساغلاملىقىنى ياخشىلايدۇ.","süt kislata baktériyiliri üchey saghlamliqini yaxshilaydu."]],"互动电视":[["互动电视增强了参与感。","ئۆزئارا تەسىرلىك تېلېۋىزىيە قاتنىشىش تۇيغۇسىنى كۈچەيتتى.","öz'ara tesirlik téléwiziye qatnishish tuyghusini kücheytti."]],"二道":[["他走二道去上班。","ئۇ ئىككىنچى يول بىلەن ئىشقا بارىدۇ.","u ikkinchi yol bilen ishqa baridu."]],"二重母音":[["这个元音是二重母音。","بۇ سوزۇق تاۋۇش ئىككى قوش سوزۇق تاۋۇشتۇر.","bu sozuq tawush ikki qosh sozuq tawushtur."]],"二刻拍案惊奇":[["《二刻拍案惊奇》是明代小说。","«ئىككى ھەجىملىك ھەيران قالدۇرۇش» مىڭ سۇلالىسى دەۋرىدىكى رومان.","«ikki hejimlik heyran qaldurush» ming sulalisi dewridiki roman."]],"五分之一":[["五分之一是0.2，在数学中常用。","بەشتىن بىرى 0.2 گە تەڭ، ماتېماتىكىدا كۆپ ئىشلىتىلىدۇ.","beshtin biri 0.2 ge teng, matématikida köp ishlitilidu."]],"亚美利加洲":[["亚美利加洲包括北美和南美。","ئامېرىكا قىتئەسى شىمالىي ئامېرىكا ۋە جەنۇبىي ئامېرىكانى ئۆز ئىچىگە ئالىدۇ.","amérika qit'esi shimaliy amérika we jenubiy amérikani öz ichige alidu."]],"五毛":[["五毛是人民币的最小单位之一。","بەش مو بىر يۈەننىڭ ئەڭ كىچىك بىرلىكلىرىنىڭ بىرىدۇر.","besh mo bir yüenning eng kichik birliklirining biridur."]],"亚马孙":[["亚马孙是南美洲最大的河流。","ئامازون جەنۇبىي ئامېرىكىدىكى ئەڭ چوڭ دەريا.","amazon jenubiy amérikidiki eng chong derya."]],"交迫":[["他被敌人的威胁所交迫投降。","ئۇ دۈشمەننىڭ تەھدىتى بىلەن قورشىلىپ تەسلىم بولدى.","u düshmenning tehditi bilen qorshilip teslim boldi."]],"亨格洛":[["亨格洛是一个古老的村庄。","ھېنگېلو قەدىمىي بىر كەنت.","héngélo qedimiy bir kent."]],"京味":[["北京菜有独特的京味。","بېيجىڭ تائاملىرى ئۆزگىچە بېيجىڭ تەمىگە ئىگە.","béyjing taamliri özgiche béyjing temige ige."]],"人比人，气死人":[["人比人，气死人，差距真大！","ئادەمنى ئادەم بىلەن سېلىشتۇرسا، ئادەمنى ئۆلتۈرىدۇ، پەرق ھەقىقەتەن چوڭ!","ademni adem bilen sélishtursa, ademni öltüridu, perq heqiqeten chong!"]],"交睫":[["他困得交睫，难以入睡。","ئۇ ئۇيقۇسى كېلىپ كۆزى ئىلىنىپ، ئۇخلاشقا قىينالدى.","u uyqusi kélip közi ilinip, uxlashqa qiynaldi."]],"人丁":[["这家店人丁兴旺，生意红火。","بۇ دۇكاننىڭ نوپۇسى گۈللەنگەن، سودىسى قىزىق.","bu dukanning nopusi güllengen, sodisi qiziq."]],"人民行动党":[["人民行动党是马来西亚的主要政党。","خەلق ھەرىكەت پارتىيىسى مالايسىيانىڭ ئاساسلىق سىياسىي پارتىيىسى.","xelq heriket partiyisi malaysiyaning asasliq siyasiy partiyisi."]],"今时今日":[["今时今日，科技发达，生活便利。","بۈگۈنكى كۈندە پەن-تېخنىكا تەرەققىي قىلغان، تۇرمۇش قولايلىق.","bügünki künde pen-téxnika tereqqiy qilghan, turmush qolayliq."]],"代人受过":[["他不愿代人受过，坚持自己的立场。","ئۇ باشقىلارنىڭ ئورنىغا ئازاب چەكمەسلىككە، ئۆز مەيدانىدا چىڭ تۇرۇشقا رازى ئەمەس.","u bashqilarning ornigha azab chekmeslikke, öz meydanida ching turushqa razi emes."]],"他者化":[["他者化过程涉及对他者的认同与接纳。","باشقىلاشتۇرۇش جەريانى باشقىلارنى تونۇش ۋە قوبۇل قىلىشنى ئۆز ئىچىگە ئالىدۇ.","bashqilashturush jeryani bashqilarni tonush we qobul qilishni öz ichige alidu."]],"仵作":[["仵作负责验尸并记录死因。","جىنايەت تەكشۈرگۈچى جەسەتنى تەكشۈرۈش ۋە ئۆلۈم سەۋەبىنى خاتىرىلەشكە مەسئۇل.","jinayet tekshürgüchi jesetni tekshürüsh we ölüm sewebini xatirileshke mes'ul."]],"伊藤博文":[["伊藤博文是日本的近代政治家。","ئىتو خاكۇبۇن ياپونىيەنىڭ يېقىنقى زامان سىياسەتچىسى.","ito xakubun yaponiyening yéqinqi zaman siyasetchisi."]],"伊春市":[["伊春市是黑龙江省的重要城市。","ئىچۈن شەھىرى خېيلۇڭجياڭ ئۆلكىسىنىڭ مۇھىم شەھىرىدۇر.","ichün shehiri xéylungjyang ölkisining muhim shehiridur."]],"佛骨塔":[["佛骨塔是保存佛舍利的地方。","بۇددا سۆڭەك مۇنارى بۇددا ساقلىقىنى ساقلايدىغان جاي.","budda söngek munari budda saqliqini saqlaydighan jay."]],"佐罗":[["佐罗是一个经典的漫画英雄。","زوررو كلاسسىك كومىكس قەھرىمانى.","zorro klassik komiks qehrimani."]],"佝偻病":[["孩子患有佝偻病，需要补钙。","بالىدا راھىت كېسىلى بار، كالتسىي تولۇقلاش كېرەك.","balida rahit késili bar, kaltsiy toluqlash kérek."]],"住家":[["他选择住在亲戚的住家，方便照顾家人。","ئۇ ئائىلىسىگە قولايلىق بولۇشى ئۈچۈن تۇغقانلىرىنىڭ ئۆيىدە تۇرۇشنى تاللىدى.","u ailisige qolayliq bolushi üchün tughqanlirining öyide turushni tallidi."]],"估价":[["专家对画作进行了估价。","مۇتەخەسسىسلەر رەسىم ئەسەرگە باھا بەردى.","mutexessisler resim eserge baha berdi."]],"伸长":[["树枝在重压下逐渐伸长，难以承受。","شاخ ئېغىر بېسىم ئاستىدا تەدرىجىي سوزۇلۇپ، چىداپ تۇرالمايدۇ.","shax éghir bésim astida tedrijiy sozulup, chidap turalmaydu."]],"依撒格":[["依撒格是亚伯拉罕的儿子。","ئىسھاق ئىبراھىمنىڭ ئوغلى.","ishaq ibrahimning oghli."]],"依附":[["植物依附在岩石上生长。","ئۆسۈملۈكلەر تاشقا تايىنىپ ئۆسىدۇ.","ösümlükler tashqa tayinip ösidu."]],"修武县":[["修武县是太极拳的发源地之一。","شىۋۇ ناھىيىسى تەيجىچۈەننىڭ مەنبە ئورۇنلىرىنىڭ بىرى.","shiwu nahiyisi teyjichüenning menbe orunlirining biri."]],"信宜市":[["信宜市以丰富的旅游资源闻名。","شىنيى شەھىرى باي ساياھەت بايلىقلىرى بىلەن داڭلىق.","shinyi shehiri bay sayahet bayliqliri bilen dangliq."]],"倘能如此":[["倘能如此，问题就解决了。","ئەگەر شۇنداق قىلغىلى بولسا، مەسىلە ھەل بولىدۇ.","eger shundaq qilghili bolsa, mesile hel bolidu."]],"假惺惺":[["他的假惺惺让人很不舒服。","ئۇنىڭ ساختا سۆيۈمچىلىكى كىشىنى بەك ناھايىتىسىز قىلىدۇ.","uning saxta söyümchiliki kishini bek nahayitisiz qilidu."]],"假扮":[["她假扮成游客参观博物馆。","ئۇ ساياھەتچى قىياپىتىگە كىرىپ مۇزېينى ئايلاندى.","u sayahetchi qiyapitige kirip muzéyni aylandi."]],"备皮":[["护士正在为手术备皮。","سېستىرا ئوپېراتسىيە ئۈچۈن تېرىنى تەييارلاۋاتىدۇ.","séstira opératsiye üchün térini teyyarlawatidu."]],"催乳":[["产后需要适当催乳。","تۇغۇتتىن كېيىن مۇۋاپىق سۈت ئاجىتىش كېرەك.","tughuttin kéyin muwapiq süt ajitish kérek."]],"传家宝":[["传家宝是家族的重要象征。","ئەجدادلاردىن قالغان خەزىنە ئائىلىنىڭ مۇھىم سىمۋولى.","ejdadlardin qalghan xezine ailining muhim simwoli."]],"催泪瓦斯":[["催泪瓦斯属于催泪剂。","كۆز ياشلىتىش گازى كۆز ياشلىتىش دورىسىغا تەۋە.","köz yashlitish gazi köz yashlitish dorisigha tewe."]],"伤别":[["伤别让球队失去了核心球员。","يارىلىنىش كوماندا ئاساسلىق توپچىسىدىن ئايرىلىپ قالدى.","yarilinish komanda asasliq topchisidin ayrilip qaldi."]],"伤身":[["熬夜会伤身，影响健康。","كېچىنى ئۇخلىماي ئۆتكۈزۈش بەدەنگە زىيان يەتكۈزۈپ، ساغلاملىققا تەسىر كۆرسىتىدۇ.","kéchini uxlimay ötküzüsh bedenge ziyan yetküzüp, saghlamliqqa tesir körsitidu."]],"充公":[["这些物品已被充公。","بۇ بۇيۇملار ئاللىبۇرۇن مۇسادىرە قىلىندى.","bu buyumlar alliburun musadire qilindi."]],"俪影":[["照片中是一对夫妻的俪影。","سۈرەتتە بىر جۈپ ئەر-خوتۇننىڭ گۈزەل سۈرىتى بار.","sürette bir jüp er-xotunning güzel süriti bar."]],"优生":[["这位优生获得了全校第一名。","بۇ ئېتىبارلىق ئوقۇغۇچى مەكتەپنىڭ بىرىنچى ئورنىنى ئالدى.","bu étibarliq oqughuchi mektepning birinchi ornini aldi."]],"元语言学意识":[["元语言学意识涉及对语言结构的觉察。","يۈەنتىلشۇناسلىق تونۇشى تىل قۇرۇلمىسىنى بايقاشنى ئۆز ئىچىگە ئالىدۇ.","yüentilshunasliq tonushi til qurulmisini bayqashni öz ichige alidu."]],"光磁碟":[["光磁碟的容量比传统光盘大。","نۇر-ماگنىت دىسكىسىنىڭ سىغىمى ئەنئەنىۋى ئوپتىك دىسكىدىن چوڭ.","nur-magnit diskisining sighimi en'eniwi optik diskidin chong."]],"全息":[["这项技术实现了全息投影。","بۇ تېخنىكا گولوگرافىيەلىك تەسۋىرلەشنى ئەمەلگە ئاشۇردى.","bu téxnika golografiyelik teswirleshni emelge ashurdi."]],"全景":[["相机支持全景拍摄功能。","كامېرا پانورامىلىق سۈرەتكە تارتىش ئىقتىدارىنى قوللايدۇ.","kaméra panoramiliq süretke tartish iqtidarini qollaydu."]],"全副":[["他全副打扮，准备出发。","ئۇ تولۇق تەييارلىق قىلىپ، يولغا چىقىشقا تەييارلاندى.","u toluq teyyarliq qilip, yolgha chiqishqa teyyarlandi."]],"入职":[["他今天正式入职公司。","ئۇ بۈگۈن رەسمىي خىزمەتكە كىردى.","u bügün resmiy xizmetke kirdi."]],"入行":[["她刚入行就表现出色。","ئۇ خىزمەتكە يېڭى كىرگەندىلا ئالاھىدە نەتىجە كۆرسەتتى.","u xizmetke yéngi kirgendila alahide netije körsetti."]],"两讫":[["双方两讫，没有遗留问题。","ئىككى تەرەپ ئىككىسى تەڭ ھېسابلاشتى، قالدۇق مەسىلە يوق.","ikki terep ikkisi teng hésablashti, qalduq mesile yoq."]],"公决":[["公决结果得到了全体民众的支持。","ئومۇمىي بېلەت تاشلاش نەتىجىسى پۈتۈن ئاممىنىڭ قوللىشىغا ئېرىشتى.","omumiy bélet tashlash netijisi pütün ammining qollishigha érishti."]],"八戒":[["八戒是《西游记》中的主要角色。","سەككىز تىيەن غەربكە سەپەر رومانىدىكى ئاساسلىق رول.","sekkiz tiyen gherbke seper romanidiki asasliq rol."]],"公开赛":[["他参加了国际公开赛。","ئۇ خەلقئارا ئوچۇق مۇسابىقىگە قاتناشتى.","u xelq'ara ochuq musabiqige qatnashti."]],"公馆乡":[["他来自公馆乡。","ئۇ قوناق يېزىسىدىن كەلگەن.","u qonaq yézisidin kelgen."]],"冤家路窄":[["冤家路窄，他们在街上意外相遇。","دۈشمەنلەر تار يولدا ئۇچرىشىپ قالدى، ئۇلار كوچىدا تاسادىپىي ئۇچراشتى.","düshmenler tar yolda uchriship qaldi, ular kochida tasadipiy uchrashti."]],"冥界":[["冥界是传说中死者的居所。","كۆرۈنمەس دۇنيا رىۋايەتتە ئۆلگەنلەرنىڭ تۇرالغۇسى.","körünmes dunya riwayette ölgenlerning turalghusi."]],"幂等":[["这个操作具有幂等性。","بۇ مەشغۇلات كۆرۈنمەس تەڭلىك خۇسۇسىيىتىگە ئىگە.","bu meshghulat körünmes tenglik xususiyitige ige."]],"冬至":[["今天就是二十四节气中的冬至。","بۈگۈن يىگىرمە تۆت قەۋسىمان پەسىلنىڭ قىش كۈنىتى.","bügün yigirme töt qewsiman pesilning qish küniti."]],"分词":[["分词是语法分析的重要步骤。","سۆز تۈركۈمى گرامماتىكىلىق ئانالىزنىڭ مۇھىم باسقۇچىدۇر.","söz türkümi grammatikiliq analizning muhim basquchidur."]],"出品":[["这部电影由知名公司出品。","بۇ كىنو تونۇلغان شىركەت تەرىپىدىن ئىشلەپچىقىرىلغان.","bu kino tonulghan shirket teripidin ishlepchiqirilghan."]],"判别":[["需要仔细判别真伪。","ھەقىقەت ۋە يالغاننى ئېنىق پەرقلەندۈرۈش كېرەك.","heqiqet we yalghanni éniq perqlendürüsh kérek."]],"削发":[["他决定削发为僧，远离尘世。","ئۇ دۇنيادىن يىراقلىشىش ئۈچۈن چېچىنى ئېلىپ راھىب بولۇشنى قارار قىلدى.","u dunyadin yiraqlishish üchün chéchini élip rahib bolushni qarar qildi."]],"锉冰":[["锉冰是台湾的特色甜点。","مۇز قىرغۇچ تەيۋەننىڭ ئالاھىدە تاتلىق تائامىدۇر.","muz qirghuch teywenning alahide tatliq taamidur."]],"前胸贴后背":[["他累得前胸贴后背。","ئۇ ھېرىپ كۆكرىكى كۆكسىگە يېقىنلاشتى.","u hérip kökriki köksige yéqinlashti."]],"刘公岛":[["刘公岛风景美。","ليۇ گۇڭدۇ ئارىلىنىڭ مەنزىرىسى گۈزەل.","lyu gungdu arilining menzirisi güzel."]],"刘晓波":[["刘晓波是著名诗人。","لىۇ شياۋبو مەشھۇر شائىر.","liu shyawbo meshhur shair."]],"力臂":[["杠杆的力臂长度影响平衡状态。","رىچاغنىڭ كۈچ بىلىكىنىڭ ئۇزۇنلۇقى تەڭپۇڭلۇق ھالىتىگە تەسىر كۆرسىتىدۇ.","richaghning küch bilikining uzunluqi tengpungluq halitige tesir körsitidu."]],"加的夫":[["加的夫是威尔士的城市。","كاردىف ئۇېلستىڭ شەھىرى.","kardif uélsting shehiri."]],"加冰块":[["加冰块能让饮料更冰爽。","مۇز پارچىلىرى قوشۇلسا ئىچىملىك تېخىمۇ مۇزلىق بولىدۇ.","muz parchiliri qoshulsa ichimlik téximu muzliq bolidu."]],"剪影":[["夕阳下的人影形成了美丽的剪影。","كۈن پېتىش مەزگىلىدىكى ئادەم سايىسى گۈزەل قىرقىما سايە شەكىللەندۈردى.","kün pétish mezgilidiki adem sayisi güzel qirqima saye shekillendürdi."]],"剪头发":[["剪头发前，理发师先咨询了需求。","چاچ قىرقىشتىن بۇرۇن، ساتىراچ تەلەپنى ئالدىن سورىدى.","chach qirqishtin burun, satirach telepni aldin soridi."]],"加速度":[["物体下落时，加速度逐渐增大。","جىسىم چۈشكەندە، تېزلىنىش تەدرىجىي ئاشىدۇ.","jisim chüshkende, tézlinish tedrijiy ashidu."]],"包公":[["包公断案十分公正。","باۋگوڭ دەۋالارنى ئىنتايىن ئادىل ھۆكۈم قىلاتتى.","bawgong dewalarni intayin adil höküm qilatti."]],"勒毙":[["罪犯被当场勒毙。","جىنايەتچى شۇ يەردە بوغۇپ ئۆلتۈرۈلدى.","jinayetchi shu yerde boghup öltürüldi."]],"勤快":[["她做事勤快，效率高。","ئۇ ئىش-ھەرىكەتتە چاققان، ئۈنۈمى يۇقىرى.","u ish-herikette chaqqan, ünümi yuqiri."]],"助人为乐":[["他助人为乐，经常帮助陌生人。","ئۇ باشقىلارغا ياردەم قىلىپ خۇشال بولىدۇ، دائىم يات كىشىلەرگە ياردەم قىلىدۇ.","u bashqilargha yardem qilip xushal bolidu, daim yat kishilerge yardem qilidu."]],"匠心独运":[["这件艺术品展现了匠心独运的创意。","بۇ سەنئەت ئەسىرى ئۆزگىچە ئىجادىيەتنى نامايان قىلدى.","bu sen'et esiri özgiche ijadiyetni namayan qildi."]],"北马里亚纳群岛":[["北马里亚纳群岛由多个岛屿组成。","شىمالىي مارىيانا ئاراللىرى نۇرغۇن ئاراللاردىن تەركىب تاپقان.","shimaliy mariyana aralliri nurghun arallardin terkib tapqan."]],"北洋军":[["北洋军是当时中国的主要军队。","شىمالىي ئوكيان ئارمىيىسى ئەينى چاغدىكى جۇڭگونىڭ ئاساسلىق ئارمىيىسى.","shimaliy okyan armiyisi eyni chaghdiki junggoning asasliq armiyisi."]],"南郊区":[["南郊区是城市的重要发展区域。","جەنۇبىي چېگرا رايونى شەھەرنىڭ مۇھىم تەرەققىيات رايونى.","jenubiy chégra rayoni sheherning muhim tereqqiyat rayoni."]],"南昌起义":[["南昌起义是中国共产党历史上的重要事件。","نەنچاڭ قوزغىلىڭى جۇڭگو كوممۇنىستىك پارتىيىسى تارىخىدىكى مۇھىم ۋەقە.","nenchang qozghilingi junggo kommunistik partiyisi tarixidiki muhim weqe."]],"博斯普鲁斯":[["博斯普鲁斯海峡连接两海。","بوسفور بوغۇزى ئىككى دېڭىزنى تۇتاشتۇرىدۇ.","bosfor boghuzi ikki déngizni tutashturidu."]],"占星学":[["占星学是一门古老的学问。","مۇنەججىملىك قەدىمىي بىر ئىلىم.","munejjimlik qedimiy bir ilim."]],"叉烧包":[["叉烧包香气扑鼻。","ئاچا كاۋاپ بولكىسىنىڭ ھىدى بۇرۇنغا ئۇرىدۇ.","acha kawap bolkisining hidi burungha uridu."]],"叉腰":[["他叉腰站在门口。","ئۇ بېلىنى تىرەپ ئىشىك ئالدىدا تۇردى.","u bélini tirep ishik aldida turdi."]],"参选":[["他宣布参选市长职位。","ئۇ شەھەر باشلىقىلىق سايلىمىغا قاتنىشىشنى ئېلان قىلدى.","u sheher bashliqiliq saylimigha qatnishishni élan qildi."]],"参量空间":[["参量空间描述了变量之间的关系。","پارامېتىر بوشلۇقى ئۆزگەرگۈچىلەر ئارىسىدىكى مۇناسىۋەتنى تەسۋىرلەيدۇ.","paramétir boshluqi özgergüchiler arisidiki munasiwetni teswirleydu."]],"原爆":[["原爆对城市造成了巨大破坏。","ئاتوم بومبىسى شەھەرگە زور ۋەيرانىلىق ئېلىپ كەلدى.","atom bombisi sheherge zor weyraniliq élip keldi."]],"反唇相讥":[["面对挑衅，他毫不客气地反唇相讥。","تەھدىتكە دۇچ كەلگەندە، ئۇ ھېچقانداق يول قويماي ئەكسىچە تىل تەگكۈزدى.","tehditke duch kelgende, u héchqandaq yol qoymay eksiche til tegküzdi."]],"反嘴":[["孩子反嘴顶撞父母，是不礼貌的表现。","بالىنىڭ ئاتا-ئانىسىغا ئەكسىچە تىل قايتۇرۇپ قارشىلىق كۆرسىتىشى ئەدەپسىزلىكتۇر.","balining ata-anisigha eksiche til qayturup qarshiliq körsitishi edepsizliktur."]],"厉行节约":[["公司倡导厉行节约，鼓励员工减少浪费。","شىركەت تېجەشلىكنى قاتتىق ئىجرا قىلىشنى تەشەببۇس قىلىپ، خىزمەتچىلەرنى ئىسراپچىلىقنى ئازايتىشقا ئىلھاملاندۇرىدۇ.","shirket téjeshlikni qattiq ijra qilishni teshebbus qilip, xizmetchilerni israpchiliqni azaytishqa ilhamlanduridu."]],"口水战":[["两人展开了激烈的口水战。","ئىككىيلەن كەسكىن سۆز جېڭى ئېچىشتى.","ikkiylen keskin söz jéngi échishti."]],"受难":[["难民在战乱中受难。","قاچقۇنلار ئۇرۇش ئاپىتىدە ئازاب چەكتى.","qachqunlar urush apitide azab chekti."]],"可回收":[["这种材料可回收再利用。","بۇ خىل ماتېرىيالنى قايتا ئىشلىتىشكە بولىدۇ.","bu xil matériyalni qayta ishlitishke bolidu."]],"古典语言":[["古典语言需要长期学习才能掌握。","كلاسسىك تىلنى ئۇزۇن مۇددەت ئۆگىنىش ئارقىلىقلا ئىگىلەلەيدۇ.","klassik tilni uzun muddet öginish arqiliqla igileleydu."]],"古惑仔":[["《古惑仔》系列电影广受欢迎。","«قەدىمكى قالاڭلار» تىياتىر فىلىمى كەڭ قارشى ئېلىنغان.","«qedimki qalanglar» tiyatir filimi keng qarshi élinghan."]],"古时候":[["古时候的人们以狩猎为生。","قەدىمكى زاماندىكى كىشىلەر ئوۋچىلىق بىلەن تۇرمۇش كەچۈرەتتى.","qedimki zamandiki kishiler owchiliq bilen turmush kechüretti."]],"史丹福大学":[["史丹福大学以科研闻名。","ستانفورد ئۇنىۋېرسىتېتى ئىلمىي تەتقىقات بىلەن داڭلىق.","stanford uniwérsitéti ilmiy tetqiqat bilen dangliq."]],"司长":[["司长是部门的最高负责人。","مۇدىر تارماقنىڭ ئەڭ يۇقىرى مەسئۇلى.","mudir tarmaqning eng yuqiri mes'uli."]],"合议庭":[["合议庭负责审理案件。","كېڭەش سوت مەھكىمىسى ئىشلارنى سوت قىلىشقا مەسئۇل.","kéngesh sot mehkimisi ishlarni sot qilishqa mes'ul."]],"另请高明":[["这件事还是另请高明处理吧。","بۇ ئىشنى يەنىلا باشقا بىر ئەقىللىق كىشىگە تاپشۇرۇپ بىر تەرەپ قىلغان ياخشى.","bu ishni yenila bashqa bir eqilliq kishige tapshurup bir terep qilghan yaxshi."]],"吉田":[["吉田是一位日本作家。","يوشىدا ياپونىيەلىك يازغۇچى.","yoshida yaponiyelik yazghuchi."]],"同胞兄妹":[["他们是同父异母的同胞兄妹。","ئۇلار ئاتا بىر ئانا بىر بولمىغان ئاكا-سىڭىللار.","ular ata bir ana bir bolmighan aka-singillar."]],"名嘴":[["这位名嘴的访谈节目很受欢迎。","بۇ داڭلىق سۆزمەننىڭ زىيارەت پىروگراممىسى ئىنتايىن ئالقىشقا ئېرىشتى.","bu dangliq sözmenning ziyaret pirogrammisi intayin alqishqa érishti."]],"名间":[["这个名间风景优美。","بۇ داڭلىق جاينىڭ مەنزىرىسى گۈزەل.","bu dangliq jayning menzirisi güzel."]],"名头":[["这个名头听起来很响亮。","بۇ نام ئاڭلىغاندا بەك جەڭگىۋار كېلىدۇ.","bu nam anglighanda bek jenggiwar kélidu."]],"吐字":[["演员的吐字必须清晰。","ئارتىسىنىڭ تەلەپپۇزى ئېنىق بولۇشى كېرەك.","artisining teleppuzi éniq bolushi kérek."]],"合式":[["这个方案非常合式。","بۇ لايىھە ئىنتايىن مۇۋاپىق.","bu layihe intayin muwapiq."]],"合弓纲":[["合弓纲是哺乳动物的祖先。","ھېگۇڭ دەرىجىسى سۈت ئەمگۈچىلەرنىڭ ئەجدادى.","hégung derijisi süt emgüchilerning ejdadi."]],"合意":[["这个提议很合意。","بۇ تەكلىپ ئىنتايىن كۆڭۈلگە ياقىدۇ.","bu teklip intayin köngülge yaqidu."]],"合气道":[["他练习合气道已有多年。","ئۇ ئاىكىدو بىلەن كۆپ يىللاردىن بېرى شۇغۇللىنىپ كېلىۋاتىدۇ.","u aikido bilen köp yillardin béri shughullinip kéliwatidu."]],"吭气":[["他终于吭气说话了。","ئۇ ئاخىرى ئاغزىنى ئېچىپ سۆزلەپ قالدى.","u axiri aghzini échip sözlep qaldi."]],"告发":[["她向警方告发盗窃行为。","ئۇ ساقچىغا ئوغرىلىق قىلمىشىنى مەلۇم قىلدى.","u saqchigha oghriliq qilmishini melum qildi."]],"吹灰之力":[["这点小事，不费吹灰之力。","بۇ كىچىك ئىش، چاڭ-توزاننى پۈۋلەشنىڭ ئەجىرىنىمۇ تەلەپ قىلمايدۇ.","bu kichik ish, chang-tozanni püwleshning ejirinimu telep qilmaydu."]],"和缓":[["他的语气非常和缓。","ئۇنىڭ ئاۋاز ئەھۋالى ئىنتايىن يۇمشاق.","uning awaz ehwali intayin yumshaq."]],"咖啡色":[["她的裙子是深咖啡色的。","ئۇنىڭ يۇبكىسى توق قەھۋە رەڭلىك.","uning yubkisi toq qehwe renglik."]],"哈巴河":[["哈巴河风景优美。","خابا دەرياسىنىڭ مەنزىرىسى گۈزەل.","xaba deryasining menzirisi güzel."]],"唐狗":[["唐狗是一种古老的犬种。","تاڭگۇ قەدىمىي بىر ئىت تۈرى.","tanggu qedimiy bir it türi."]],"唐诗":[["唐诗是中国古典文学的瑰宝。","تەڭشىنات شېئىرىيىتى جۇڭگو كلاسسىك ئەدەبىياتىنىڭ گۆھىرىدۇر.","tengshinat shéiriyiti junggo klassik edebiyatining göhiridur."]],"唯恐天下不乱":[["他唯恐天下不乱。","ئۇ پەقەت دۇنيانىڭ قالايمىقان بولۇپ كېتىشىدىن قورقىدۇ.","u peqet dunyaning qalaymiqan bolup kétishidin qorqidu."]],"喀土穆":[["喀土穆是苏丹的首都城市。","خارتىتۇم سۇداننىڭ پايتەخت شەھىرىدۇر.","xartitum sudanning paytext shehiridur."]],"唱盘":[["唱盘是唱机的核心部件。","ئاۋاز پلاستىنكىسى ئاۋاز ماشىنىسىنىڭ يادرولۇق زاپچاسى.","awaz plastinkisi awaz mashinisining yadroluq zapchasi."]],"唱红脸":[["他唱红脸，缓和了气氛。","ئۇ ساقال-بۇرۇت رولىنى ئويناپ، كەيپىياتنى يۇمشاتتى.","u saqal-burut rolini oynap, keypiyatni yumshatti."]],"乔治城":[["乔治城是马里兰州的城市。","جورجتاۋ مېرىلاند شتاتىدىكى بىر شەھەر.","jorjtaw mériland shtatidiki bir sheher."]],"单眼皮":[["她的眼睛是单眼皮的。","ئۇنىڭ كۆزلىرى يالغۇز قاپاقلىق.","uning közliri yalghuz qapaqliq."]],"吓人":[["这个故事听起来很吓人。","بۇ ھېكايە ئاڭلىغىلى بەك قورقۇنچلۇق.","bu hékaye anglighili bek qorqunchluq."]],"回纥":[["回纥人曾是古代丝绸之路的重要民族。","ئۇيغۇرلار قەدىمكى يىپەك يولىدىكى مۇھىم مىللەت بولغان.","uyghurlar qedimki yipek yolidiki muhim millet bolghan."]],"回春":[["春天到来，万物开始回春。","باھار كەلدى، ھەممە نەرسە باھارغا قايتىشقا باشلىدى.","bahar keldi, hemme nerse bahargha qaytishqa bashlidi."]],"国家主义":[["国家主义强调国家利益至上。","مىللەتچىلىك دۆلەت مەنپەئەتىنىڭ ئەڭ ئالىيلىقىنى تەكىتلەيدۇ.","milletchilik dölet menpeetining eng aliyliqini tekitleydu."]],"固态":[["固态物质在常温下保持稳定。","قاتتىق ھالەتتىكى ماددا نورمال تېمپېراتۇرىدا مۇقىملىقىنى ساقلايدۇ.","qattiq halettiki madda normal témpératurida muqimliqini saqlaydu."]],"土堆":[["山丘上有一个巨大的土堆。","تۆپىلىكتە بىر غايەت زور توپا دۆۋىسى بار.","töpilikte bir ghayet zor topa döwisi bar."]],"围击":[["敌人从多个方向发起围击。","دۈشمەنلەر كۆپ يۆنىلىشتىن قورشاپ ھۇجۇم قىلدى.","düshmenler köp yönilishtin qorshap hujum qildi."]],"圆融":[["他的为人处事十分圆融。","ئۇنىڭ ئادەم بىلەن ئۆتۈشۈشى ئىنتايىن يۇمشاق.","uning adem bilen ötüshüshi intayin yumshaq."]],"国际大赦":[["国际大赦组织呼吁停止战争。","خەلقئارا ئامنىستىي تەشكىلاتى ئۇرۇشنى توختىتىشقا چاقىرىدۇ.","xelq'ara amnistiy teshkilati urushni toxtitishqa chaqiridu."]],"土耳其玉":[["土耳其玉是一种珍贵的宝石材料。","تۈركىيە يۈزى قىممەتلىك مەرۋايىت ماتېرىيالىدۇر.","türkiye yüzi qimmetlik merwayit matériyalidur."]],"国情咨文":[["总统在国情咨文中阐述政策方向。","پىرېزىدېنت دۆلەت ئەھۋالى دوكلاتىدا سىياسەت يۆنىلىشىنى شەرھلەيدۇ.","pirézidént dölet ehwali doklatida siyaset yönilishini sherhleydu."]],"地雷":[["地雷是一种隐藏在地下的爆炸装置。","مىنا يەر ئاستىغا يوشۇرۇلغان بىر خىل پارتلىتىش ئۈسكۈنىسىدۇر.","mina yer astigha yoshurulghan bir xil partlitish üskünisidur."]],"基本点":[["抓住基本点就能成功。","ئاساسىي نۇقتىنى تۇتۇپ قالسىلا مۇۋەپپەقىيەت قازىنىسىز.","asasiy nuqtini tutup qalsila muweppeqiyet qazinisiz."]],"基极":[["电子管的基极很重要。","ئېلېكترونلۇق نەيچىنىڭ ئاساسىي قۇتۇبى ناھايىتى مۇھىمدۇر.","éléktronluq neychining asasiy qutubi nahayiti muhimdur."]],"坚固性":[["这种材料的坚固性令人满意。","بۇ خىل ماتېرىيالنىڭ جىيەنگۇچىلىقى كىشىنى قانائەتلەندۈرىدۇ.","bu xil matériyalning jiyenguchiliqi kishini qanaetlendüridu."]],"坚振礼":[["坚振礼象征信徒的成熟。","جىيەنجېن مۇراسىمى مۇئمىنلەرنىڭ يېتىلىشىنى سىمۋوللايدۇ.","jiyenjén murasimi muminlerning yétilishini simwollaydu."]],"墓场":[["这座墓场已有数百年历史。","بۇ قەبرىستانلىقنىڭ تارىخى نەچچە يۈز يىل بولغان.","bu qebristanliqning tarixi nechche yüz yil bolghan."]],"堕楼":[["他因抑郁而选择堕楼。","ئۇ چۈشكۈنلۈك سەۋەبىدىن بىنا ئۈستىدىن چۈشۈشنى تاللىدى.","u chüshkünlük sewebidin bina üstidin chüshüshni tallidi."]],"壬申":[["壬申年出现了罕见的天文现象。","رېن-شېن يىلى كام ئۇچرايدىغان ئاسترونومىيە ھادىسىسى كۆرۈلدى.","rén-shén yili kam uchraydighan astronomiye hadisisi körüldi."]],"寿带":[["他戴了一条红色的寿带。","ئۇ قىزىل رەڭلىك شوەندەي تاقىۋالغان.","u qizil renglik shoendey taqiwalghan."]],"外满洲":[["外满洲在历史上属于争议地区。","سىرتقى مانجۇرىيە تارىختا تالاش-تارتىشلىق رايون ھېسابلىنىدۇ.","sirtqi manjuriye tarixta talash-tartishliq rayon hésablinidu."]],"多寡":[["多寡取决于个人选择。","ئاز-كۆپلۈكى شەخسىي تاللاشقا باغلىق.","az-köplüki shexsiy tallashqa baghliq."]],"多层大厦":[["这座多层大厦有五十层楼高。","بۇ كۆپ قەۋەتلىك بىنا ئەللىك قەۋەت ئېگىز.","bu köp qewetlik bina ellik qewet égiz."]],"梦中":[["他在梦中见到了久别的朋友。","ئۇ چۈشىدە ئۇزۇن زامان كۆرۈشمىگەن دوستىنى كۆردى.","u chüshide uzun zaman körüshmigen dostini kördi."]],"大城":[["大城是古代重要的军事要塞。","داچېڭ قەدىمدە مۇھىم ھەربىي قورغان ئىدى.","dachéng qedimde muhim herbiy qorghan idi."]],"大屠杀":[["大屠杀令人痛彻心扉。","چوڭ قىرغىنچىلىق كىشىنىڭ يۈرىكىنى ئېزىپ تاشلايدۇ.","chong qirghinchiliq kishining yürikini ézip tashlaydu."]],"大姨妈":[["大姨妈来月经时需要注意休息。","چوڭ ئاپام ھەيز كۆرگەن چاغدا ئارام ئېلىشقا دىققەت قىلىشى كېرەك.","chong apam heyz körgen chaghda aram élishqa diqqet qilishi kérek."]],"大树菠萝":[["大树菠萝是一种热带水果。","چوڭ دەرەخ ئاناناسى بىر تروپىك مېۋە.","chong derex ananasi bir tropik méwe."]],"大氧吧":[["这里的大氧吧空气清新，让人神清气爽。","بۇ يەردىكى چوڭ ئوكسىگېنلىق جاينىڭ ھاۋاسى تازا بولۇپ، ئادەمنى روھلاندۇرىدۇ.","bu yerdiki chong oksigénliq jayning hawasi taza bolup, ademni rohlanduridu."]],"多模":[["这款设备支持多模操作。","بۇ ئۈسكۈنە كۆپ ھالەتلىك مەشغۇلاتنى قوللايدۇ.","bu üsküne köp haletlik meshghulatni qollaydu."]],"大藏经":[["大藏经是佛教的经典文献。","بۈيۈك خەزىنە ئىزچىلىكى بۇددا دىنىنىڭ كلاسسىك ئەسەرلىرىدۇر.","büyük xezine izchiliki budda dinining klassik eserliridur."]],"大野":[["大野是著名的探险家。","دايې مەشھۇر تەكشۈرۈشچى.","dayé meshhur tekshürüshchi."]],"大长腿":[["她有一双大长腿。","ئۇنىڭ ئىككى چوڭ ئۇزۇن پۇتى بار.","uning ikki chong uzun puti bar."]],"大杂院":[["大杂院里住着许多邻居。","ئارىلاش ھويلىدا نۇرغۇن قوشنىلار ئولتۇرىدۇ.","arilash hoylida nurghun qoshnilar olturidu."]],"大雨如注":[["大雨如注，街道积水成河。","چوڭ يامغۇر قۇيۇپ، كوچىلاردا سۇ جىلغىغا ئايلاندى.","chong yamghur quyup, kochilarda su jilghigha aylandi."]],"天成":[["这幅画作堪称天成之作。","بۇ رەسىم تەبىئىي يارىتىلغان ئەسەر دېيىشكە بولىدۇ.","bu resim tebiiy yaritilghan eser déyishke bolidu."]],"天体物理":[["天体物理涉及星体的物理特性分析。","ئاسمان جىسىملىرى فىزىكىسى يۇلتۇز جىسىملىرىنىڭ فىزىكىلىق خۇسۇسىيەتلىرىنى تەھلىل قىلىشنى ئۆز ئىچىگە ئالىدۇ.","asman jisimliri fizikisi yultuz jisimlirining fizikiliq xususiyetlirini tehlil qilishni öz ichige alidu."]],"天老儿":[["天老儿是民间传说中的神仙。","ئاسمان ئەھلىسى خەلق ئەپسانىلىرىدىكى ئىلاھتۇر.","asman ehlisi xelq epsaniliridiki ilahtur."]],"天罡星":[["天罡星是《水浒传》中的英雄人物。","تيەنگاڭ يۇلتۇزى «سۇ بويىدا» رومانىدىكى قەھرىمان شەخستۇر.","tyengang yultuzi «su boyida» romanidiki qehriman shexstur."]],"大赦国际":[["大赦国际组织关注全球人权问题。","ئامنېستىي خەلقئارا تەشكىلاتى دۇنيادىكى ئىنسان ھوقۇقى مەسىلىسىگە دىققەت قىلىدۇ.","amnéstiy xelq'ara teshkilati dunyadiki insan hoquqi mesilisige diqqet qilidu."]],"失之毫厘，谬以千里":[["失之毫厘，谬以千里，细节决定成败。","كىچىك خاتالىق چوڭ پەرقنى كەلتۈرۈپ چىقىرىدۇ، تەپسىلات مۇۋەپپەقىيەت-مەغلۇبىيەتنى بەلگىلەيدۇ.","kichik xataliq chong perqni keltürüp chiqiridu, tepsilat muweppeqiyet-meghlubiyetni belgileydu."]],"奉新":[["奉新是江西省的一个县。","فېڭشىن جياڭشى ئۆلكىسىدىكى بىر ناھىيەدۇر.","féngshin jyangshi ölkisidiki bir nahiyedur."]],"奉现":[["奉现是一种支付方式。","بېغىشلاش بىر خىل تۆلەم ئۇسۇلىدۇر.","béghishlash bir xil tölem usulidur."]],"太平洋区域":[["太平洋区域是全球气候的重要影响因素。","تىنچ ئوكيان رايونى پۈتۈن يەرشارى ئىقلىمىنىڭ مۇھىم تەسىر كۆرسىتىش ئامىلى.","tinch okyan rayoni pütün yershari iqlimining muhim tesir körsitish amili."]],"太极图":[["太极图象征着阴阳平衡的哲学思想。","تەيجى سۈرىتى يىن-ياڭ تەڭپۇڭلۇقى پەلسەپىسىنى سىمۋوللاشتۇرىدۇ.","teyji süriti yin-yang tengpungluqi pelsepisini simwollashturidu."]],"奔四":[["她即将奔四。","ئۇ قىرىق ياشقا يېقىنلاپ قالدى.","u qiriq yashqa yéqinlap qaldi."]],"天赐":[["这份礼物是上天赐予的。","بۇ سوۋغات تەڭرى تەرىپىدىن ئاتا قىلىنغان.","bu sowghat tengri teripidin ata qilinghan."]],"女生外向":[["这个女生外向，喜欢社交。","بۇ قىز ئوچۇق چىرايلىق، ئىجتىمائىي ئالاقىگە ئامراق.","bu qiz ochuq chirayliq, ijtimaiy alaqige amraq."]],"夺魁":[["他在比赛中夺魁成功。","ئۇ مۇسابىقىدە غەلىبە قىلىشقا مۇيەسسەر بولدى.","u musabiqide ghelibe qilishqa muyesser boldi."]],"奋进号":[["奋进号飞船成功返回地球。","فېنجىن ناملىق ئالەم كېمىسى يەر شارىغا مۇۋەپپەقىيەتلىك قايتتى.","fénjin namliq alem kémisi yer sharigha muweppeqiyetlik qaytti."]],"奥卡姆剃刀":[["这个理论遵循奥卡姆剃刀原则。","بۇ نەزەرىيە ئوككام ئۇستۇرىسى پرىنسىپىغا ئەمەل قىلىدۇ.","bu nezeriye okkam usturisi prinsipigha emel qilidu."]],"如草":[["野花如草般随意生长。","ياۋا گۈللەر ئوتتەك ئەركىن ئۆسىدۇ.","yawa güller ottek erkin ösidu."]],"奸宿":[["奸宿指强行与女性发生性关系。","زىنا قىلىش ئايالغا زورلۇق بىلەن جىنسىي مۇناسىۋەت ئۆتكۈزۈشنى كۆرسىتىدۇ.","zina qilish ayalgha zorluq bilen jinsiy munasiwet ötküzüshni körsitidu."]],"子虚乌有":[["这件事完全是子虚乌有的。","بۇ ئىش پۈتۈنلەي ئاساسسىز يالغاندۇر.","bu ish pütünley asassiz yalghandur."]],"孔雀河":[["孔雀河是一条内陆河。","توزغۇن دەرياسى ئىچكى قۇرۇقلۇق دەرياسى.","tozghun deryasi ichki quruqluq deryasi."]],"字图":[["字图展示了汉字的演变过程。","ھەرپ رەسىمى خەنزۇ يېزىقىنىڭ تەرەققىيات جەريانىنى كۆرسىتىدۇ.","herp resimi xenzu yéziqining tereqqiyat jeryanini körsitidu."]],"季刊":[["这本杂志是季刊。","بۇ ژۇرنال پەسلىي نەشر قىلىنىدۇ.","bu zhurnal pesliy neshr qilinidu."]],"存食":[["动物在冬季会储存食物以度过严寒。","ھايۋانلار قىشتا سوغۇقتىن ئۆتۈش ئۈچۈن يېمەكلىك ساقلايدۇ.","haywanlar qishta soghuqtin ötüsh üchün yémeklik saqlaydu."]],"安新":[["安新是个美丽的地方。","ئەنشىن گۈزەل بىر جاي.","enshin güzel bir jay."]],"孟婆":[["孟婆在阴间负责熬制孟婆汤。","مېڭپو ئاخرەتتە مېڭپو شورپىسىنى قاينىتىشقا مەسئۇل.","méngpo axrette méngpo shorpisini qaynitishqa mes'ul."]],"孤身":[["他孤身一人前往远方。","ئۇ يالغۇز ئۆزى يىراق يەرگە باردى.","u yalghuz özi yiraq yerge bardi."]],"孩提":[["孩提时的回忆总是令人怀念。","بالىلىق چاغدىكى ئەسلىمىلەر ھەمىشە سېغىندۇرىدۇ.","baliliq chaghdiki eslimiler hemishe séghinduridu."]],"安全带":[["上车后务必系好安全带。","ماشىنىغا چىققاندىن كېيىن چوقۇم بىخەتەرلىك بەلبېغىنى باغلىشى كېرەك.","mashinigha chiqqandin kéyin choqum bixeterlik belbéghini baghlishi kérek."]],"安乡县":[["安乡县盛产大米。","ئەنشياڭ ناھىيىسى گۈرۈچكە باي.","enshyang nahiyisi gürüchke bay."]],"安闲自在":[["退休后生活安闲自在。","تەقاۋۇتتىن كېيىنكى تۇرمۇش پەرۋايانلىق ۋە ئەركىن.","teqawuttin kéyinki turmush perwayanliq we erkin."]],"宋史":[["《宋史》是记载宋代历史的史书。","«سۇڭ تارىخى» سۇڭ سۇلالىسى تارىخىنى خاتىرىلىگەن تارىخىي كىتاب.","«sung tarixi» sung sulalisi tarixini xatiriligen tarixiy kitab."]],"宗教仪式":[["这场宗教仪式吸引了大量信徒。","بۇ دىنىي مۇراسىم كۆپ ساندىكى مۇئمىنلەرنى جەلپ قىلدى.","bu diniy murasim köp sandiki muminlerni jelp qildi."]],"宗派":[["不同宗派之间存在明显的差异。","تۈرلۈك مەزھەبلەر ئارىسىدا ئېنىق پەرق بار.","türlük mezhebler arisida éniq perq bar."]],"客观性":[["实验结果的客观性至关重要。","تەجرىبە نەتىجىسىنىڭ ئوبيېكتىپلىقى ئىنتايىن مۇھىم.","tejribe netijisining obyéktipliqi intayin muhim."]],"宣化区":[["宣化区位于河北省的西北部。","شۈەنخۇا رايونى خېبېي ئۆلكىسىنىڭ شىمالىي غەربىدە جايلاشقان.","shüenxua rayoni xébéy ölkisining shimaliy gherbide jaylashqan."]],"密植":[["科学家研究了植物的密植技术。","ئالىملار ئۆسۈملۈكلەرنىڭ قويۇق تىكىش تېخنىكىسىنى تەتقىق قىلدى.","alimlar ösümlüklerning qoyuq tikish téxnikisini tetqiq qildi."]],"家庭主夫":[["他是一位全职的家庭主夫。","ئۇ تولۇق ۋاقىتلىق ئائىلە ئېرى.","u toluq waqitliq aile éri."]],"家庭地址":[["请提供你的家庭地址。","ئائىلە ئادرېسىڭىزنى تەمىنلەڭ.","aile adrésingizni teminleng."]],"察合台":[["察合台汗国是中亚历史上的重要政权。","چاغاتاي خانلىقى ئوتتۇرا ئاسىيا تارىخىدىكى مۇھىم ھاكىمىيەت.","chaghatay xanliqi ottura asiya tarixidiki muhim hakimiyet."]],"射手":[["这位射手在比赛中表现优异。","بۇ ئاتقۇچى مۇسابىقىدە ئالاھىدە نەتىجە كۆرسەتتى.","bu atquchi musabiqide alahide netije körsetti."]],"封建主义":[["封建主义是一种以土地私有制为基础的社会制度。","فېئودالىزم يەرنىڭ خۇسۇسىي مۈلۈكچىلىكىگە ئاساسلانغان ئىجتىمائىي تۈزۈم.","féodalizm yerning xususiy mülükchilikige asaslanghan ijtimaiy tüzüm."]],"射程":[["这款枪的有效射程超过五百米。","بۇ مىلتىقنىڭ ئۈنۈملۈك ئېتىش ئارىلىقى بەش يۈز مېتىردىن ئاشىدۇ.","bu miltiqning ünümlük étish ariliqi besh yüz métirdin ashidu."]],"小便斗":[["公共厕所的小便斗很干净。","ئاممىۋى ھاجەتخانىدىكى سۈيدۈك چىقىرىش ئەسۋابى ناھايىتى تازا.","ammiwi hajetxanidiki süydük chiqirish eswabi nahayiti taza."]],"专区":[["这个专区负责管理边境地区的贸易事务。","بۇ مەخسۇس رايون چېگرا رايونلىرىنىڭ سودا ئىشلىرىنى باشقۇرۇشقا مەسئۇل.","bu mexsus rayon chégra rayonlirining soda ishlirini bashqurushqa mes'ul."]],"专家系统":[["这款人工智能专家系统能准确诊断复杂疾病。","بۇ سۈنئىي ئەقىل مۇتەخەسسىس سىستېمىسى مۇرەككەپ كېسەللىكلەرنى توغرا دىئاگنوز قىلالايدۇ.","bu sün'iy eqil mutexessis sistémisi murekkep késelliklerni toghra diagnoz qilalaydu."]],"寻欢":[["他们去寻欢作乐。","ئۇلار كۆڭۈل ئېچىش ئۈچۈن باردى.","ular köngül échish üchün bardi."]],"将才":[["他是一位有战略眼光的将才。","ئۇ ئىستراتېگىيەلىك كۆز قاراشقا ئىگە جياڭسەي.","u istratégiyelik köz qarashqa ige jyangsey."]],"小手小脚":[["孩子的小手小脚，看起来格外可爱。","بالىنىڭ كىچىك قول-پۇتلىرى ئالاھىدە يېقىملىق كۆرۈنىدۇ.","balining kichik qol-putliri alahide yéqimliq körünidu."]],"小轮车":[["小轮车速度很快。","كىچىك چاقلىق ۋېلىسىپېتنىڭ سۈرئىتى ناھايىتى تېز.","kichik chaqliq wélisipétning sür'iti nahayiti téz."]],"尖头鱥":[["尖头鱥是一种生活在淡水中的鱼。","باشلىق بېلىق تاتلىق سۇدا ياشايدىغان بىر خىل بېلىق.","bashliq béliq tatliq suda yashaydighan bir xil béliq."]],"尺码":[["请确认鞋子的尺码是否准确。","ئاياغنىڭ ئۆلچىمىنىڭ توغرا ياكى ئەمەسلىكىنى جەزملەشتۈرۈڭ.","ayaghning ölchimining toghra yaki emeslikini jezmleshtürüng."]],"小灶":[["小灶常用于家庭烹饪。","كىچىك ئوچاق ئادەتتە ئائىلە تاماق ئېتىشىدە ئىشلىتىلىدۇ.","kichik ochaq adette aile tamaq étishide ishlitilidu."]],"尖扎县":[["尖扎县以草原闻名。","جىيەنجا ناھىيىسى يايلاق بىلەن داڭلىق.","jiyenja nahiyisi yaylaq bilen dangliq."]],"居第":[["居第是古代的一种官职。","جۈدى قەدىمكى زاماندا بىر خىل ئەمەلدارلىق ئورنى ئىدى.","jüdi qedimki zamanda bir xil emeldarliq orni idi."]],"岢岚县":[["岢岚县以独特的黄土景观著称。","كېلەن ناھىيىسى ئۆزگىچە لۆس توپا مەنزىرىسى بىلەن تونۇلغان.","kélen nahiyisi özgiche lös topa menzirisi bilen tonulghan."]],"岑巩县":[["岑巩县位于贵州省东南部。","تسېنگۇڭ ناھىيىسى گۈيژۇ ئۆلكىىسىنىڭ شەرقىي جەنۇبىدا جايلاشقان.","tséngung nahiyisi güyzhu ölkiisining sherqiy jenubida jaylashqan."]],"川资":[["川资指四川地区的资金流动。","چۈەنزى سىچۈەن رايونىنىڭ مەبلەغ ئوبوروتىنى كۆرسىتىدۇ.","chüenzi sichüen rayonining meblegh oborotini körsitidu."]],"岩盐":[["岩盐是直接从岩石中开采的矿物。","تاش تۇزى بىۋاسىتە تاشتىن قېزىپ ئېلىنىدىغان مىنېرال.","tash tuzi biwasite tashtin qézip élinidighan minéral."]],"巫毒":[["巫毒是一种神秘的宗教仪式。","ۋۇدۇ بىر خىل سىرلىق دىنىي مۇراسىم.","wudu bir xil sirliq diniy murasim."]],"巧言令色":[["他巧言令色，让人难以拒绝。","ئۇنىڭ ماھىرانە سۆزلىرى ۋە يېقىملىق چىرايى كىشىنىڭ رەت قىلىشىنى قىيىنلاشتۇرىدۇ.","uning mahirane sözliri we yéqimliq chirayi kishining ret qilishini qiyinlashturidu."]],"巴马县":[["巴马县是广西壮族自治区的一个县。","باما ناھىيىسى گۇاڭشى جۇاڭزۇ ئاپتونوم رايونىنىڭ بىر ناھىيىسى.","bama nahiyisi guangshi juangzu aptonom rayonining bir nahiyisi."]],"布莱氏鹨":[["布莱氏鹨是一种珍稀的鸟类。","بىرايېل تىلىق چىۋىقىن ناچار قۇشلارنىڭ بىر تۈرىدۇر.","birayél tiliq chiwiqin nachar qushlarning bir türidur."]],"帕格尼尼":[["帕格尼尼是一位伟大的小提琴家。","پاگانىنى ئۇلۇغ بىر سكرىپكىچى ئىدى.","paganini ulugh bir skripkichi idi."]],"帕特里夏":[["帕特里夏在会议上发表了演讲。","پاترىشا يىغىندا نۇتۇق سۆزلىدى.","patrisha yighinda nutuq sözlidi."]],"布里斯班":[["布里斯班是澳大利亚的第三大城市。","بۇرىسبان ئاۋسترالىيەنىڭ ئۈچىنچى چوڭ شەھىرىدۇر.","burisban awstraliyening üchinchi chong shehiridur."]],"带岭":[["带岭是黑龙江省的县。","دەيلېڭ خېيلۇڭجياڭ ئۆلكىسىنىڭ بىر ناھىيىسى.","deyléng xéylungjyang ölkisining bir nahiyisi."]],"平定":[["军队成功平定了叛乱。","ئارمىيە ئىسياننى مۇۋەپپەقىيەتلىك باستى.","armiye isyanni muweppeqiyetlik basti."]],"广南县":[["广南县是云南省的一个少数民族县。","گۇاڭنەن ناھىيىسى يۈننەن ئۆلكىسىدىكى بىر ئاز سانلىق مىللەت ناھىيىسىدۇر.","guangnen nahiyisi yünnen ölkisidiki bir az sanliq millet nahiyisidur."]],"广宗县":[["广宗县以盛产优质小麦而闻名。","گۇاڭزۇڭ ناھىيىسى ئەلا سۈپەتلىك بۇغداي ئىشلەپچىقىرىشى بىلەن داڭلىقتۇر.","guangzung nahiyisi ela süpetlik bughday ishlepchiqirishi bilen dangliqtur."]],"强征":[["强征劳役在古代十分普遍。","كۈچ بىلەن ئەمگەككە زورلاش قەدىمدە ئىنتايىن ئومۇمىي ئىدى.","küch bilen emgekke zorlash qedimde intayin omumiy idi."]],"强流":[["强流明星的演唱会门票难求。","كۈچلۈك ئاققان يۇلتۇزنىڭ كونسېرتى بېلىتى تېپىش قىيىن.","küchlük aqqan yultuzning konsérti béliti tépish qiyin."]],"廊庑":[["廊庑是房屋周围的回廊。","لاڭۋۇ ئۆي ئەتراپىدىكى ئايلانما يول.","langwu öy etrapidiki aylanma yol."]],"弟兄们":[["弟兄们一起完成了任务。","ئاكا-ئۇكا-ئاچا-سىڭىللار بىرلىكتە ۋەزىپىنى ئورۇندىدى.","aka-uka-acha-singillar birlikte wezipini orundidi."]],"弧线长":[["弧线长度适中。","قەۋس سىزىقىنىڭ ئۇزۇنلۇقى مۇۋاپىق.","qews siziqining uzunluqi muwapiq."]],"引咎辞职":[["因失误，他选择引咎辞职。","خاتالىق سەۋەبىدىن، ئۇ جاۋابكارلىقنى ئۈستىگە ئېلىپ ئىستېپا بېرىشنى تاللىدى.","xataliq sewebidin, u jawabkarliqni üstige élip istépa bérishni tallidi."]],"弹珠":[["孩子们在玩弹珠游戏。","بالىلار مەرۋايىت ئويۇنى ئويناۋاتىدۇ.","balilar merwayit oyuni oynawatidu."]],"征讨":[["军队开始征讨叛军。","ئارمىيە ئىسيانچى قوشۇنغا قارشى جەڭ قىلىشنى باشلىدى.","armiye isyanchi qoshungha qarshi jeng qilishni bashlidi."]],"徒步区":[["这里是禁止车辆的徒步区。","بۇ يەر ماشىنىلار مەنئى قىلىنغان پىيادە مېڭىش رايونى.","bu yer mashinilar men'i qilinghan piyade méngish rayoni."]],"从何":[["问题从何而来？","مەسىلە نەدىن كەلدى؟","mesile nedin keldi?"]],"后燕":[["后燕与北魏长期对抗。","كېيىنكى يەن بىلەن شىمالىي ۋېي ئۇزۇن مۇددەت قارشىلاشتى.","kéyinki yen bilen shimaliy wéy uzun muddet qarshilashti."]],"从难从严":[["训练要从难从严。","مەشىق قىيىن ۋە قاتتىق تەلەپلەر بويىچە ئېلىپ بېرىلىشى كېرەك.","meshiq qiyin we qattiq telepler boyiche élip bérilishi kérek."]],"微凹黄檀":[["微凹黄檀是一种珍贵木材。","مىكرو ئويۇق سېرىق سەندەل قىممەتلىك ياغاچ تۈرىدۇر.","mikro oyuq sériq sendel qimmetlik yaghach türidur."]],"心静自然凉":[["心静自然凉，烦恼都消散了。","كۆڭۈل تىنچ بولسا تەبىئىي سالقىن بولىدۇ، غەم-قايغۇلار يوقىلىدۇ.","köngül tinch bolsa tebiiy salqin bolidu, ghem-qayghular yoqilidu."]],"德令哈市":[["德令哈市以草原闻名。","دېلېڭخا شەھىرى يايلاق بىلەن داڭلىق.","déléngxa shehiri yaylaq bilen dangliq."]],"必死无疑":[["他必死无疑。","ئۇ چوقۇم ئۆلىدۇ، شەك يوق.","u choqum ölidu, shek yoq."]],"心智图":[["心智图能帮助理清思路。","ئەقلىي خەرىتە چۈشەنچىنى ئېنىقلىشقا ياردەم قىلالايدۇ.","eqliy xerite chüshenchini éniqlishqa yardem qilalaydu."]],"忍者龟":[["忍者龟是《忍者神龟》的主角。","نىنجا تاشپاقىسى «نىنجا تاشپاقىسى» نىڭ باش پېرسوناژى.","ninja tashpaqisi «ninja tashpaqisi» ning bash pérsonazhi."]],"忙着":[["他忙着开会，没时间说话。","ئۇ يىغىن بىلەن ئالدىراش بولۇپ، سۆزلىشىشكە ۋاقتى يوق.","u yighin bilen aldirash bolup, sözlishishke waqti yoq."]],"性激素":[["性激素调控着人体的发育与行为。","جىنسىي ھورمونلار ئىنسان بەدىنىنىڭ ئۆسۈشى ۋە ھەرىكىتىنى تەڭشەيدۇ.","jinsiy hormonlar insan bedinining ösüshi we herikitini tengsheydu."]],"恩赐":[["这份恩赐让我一生难忘。","بۇ ئىنئام مېنى ئۆمۈر بويى ئۇنتۇلالمايدىغان قىلدى.","bu in'am méni ömür boyi untulalmaydighan qildi."]],"悉数":[["他悉数数清了桌上的所有硬币。","ئۇ ئۈستەلدىكى بارلىق تەڭگىلەرنى بىر-بىرلەپ سانىدى.","u üsteldiki barliq tenggilerni bir-birlep sanidi."]],"患上":[["他患上了严重的感冒。","ئۇ ئېغىر زۇكامغا گىرىپتار بولدى.","u éghir zukamgha giriptar boldi."]],"恤衫":[["她穿着舒适的恤衫。","ئۇ راھەت كۆڭلەك كىيىپتى.","u rahet könglek kiyipti."]],"悲叹":[["他对着天空发出悲叹。","ئۇ ئاسمانغا قاراپ قايغۇرۇپ ئاھ ئۇردى.","u asmangha qarap qayghurup ah urdi."]],"意想不到":[["这件事完全意想不到。","بۇ ئىش پۈتۈنلەي كۈتۈلمىگەن ئىدى.","bu ish pütünley kütülmigen idi."]],"惨景":[["眼前的惨景让人心碎。","كۆز ئالدىدىكى ئېچىنىشلىق مەنزىرە كىشىنىڭ يۈرىكىنى ئېزىدۇ.","köz aldidiki échinishliq menzire kishining yürikini ézidu."]],"应力":[["材料能承受多大的应力？","ماتېرىيال قانچىلىك بېسىمغا بەرداشلىق بېرەلەيدۇ؟","matériyal qanchilik bésimgha berdashliq béreleydu?"]],"悬河":[["他的口才如悬河滔滔，令人叹为观止。","ئۇنىڭ سۆز-چېچەنلىكى ئېقىن سۇدەك تاشقىن بولۇپ، كىشىنى ھەيران قالدۇرىدۇ.","uning söz-chéchenliki éqin sudek tashqin bolup, kishini heyran qalduridu."]],"戏偶":[["戏偶是传统戏剧的重要道具。","قورچاق تىياتىرى ئەنئەنىۋى تىياتىرنىڭ مۇھىم ئەسۋابى.","qorchaq tiyatiri en'eniwi tiyatirning muhim eswabi."]],"我司":[["我司最近推出了新产品。","شىركىتىمىز يېقىندا يېڭى مەھسۇلاتلارنى تونۇشتۇردى.","shirkitimiz yéqinda yéngi mehsulatlarni tonushturdi."]],"戒严区":[["戒严区内禁止任何车辆随意通行。","قاتتىق قوغدىلىش رايونىدا ھەر قانداق ماشىنىنىڭ خالىغانچە يۈرۈشى چەكلىنىدۇ.","qattiq qoghdilish rayonida her qandaq mashinining xalighanche yürüshi cheklinidu."]],"恋脚癖":[["他患有罕见的恋脚癖。","ئۇ كام ئۇچرايدىغان پۇتқا كۆڭۈل باغلاش كېسىلىگە گىرىپتار.","u kam uchraydighan putқa köngül baghlash késilige giriptar."]],"所指":[["这个词所指的具体含义需要解释。","بۇ سۆزنىڭ كۆرسىتىدىغان كونكرېت مەنىسىنى چۈشەندۈرۈشكە توغرا كېلىدۇ.","bu sözning körsitidighan konkrét menisini chüshendürüshke toghra kélidu."]],"打牙祭":[["周末他特意打牙祭吃顿好的。","ھەپتە ئاخىرى ئۇ ئالاھىدە ياخشى تاماق يېيىش ئۈچۈن تەييارلىق قىلدى.","hepte axiri u alahide yaxshi tamaq yéyish üchün teyyarliq qildi."]],"手摇饮料":[["手摇饮料机操作简单又有趣。","قول بىلەن ئايلاندۇرىدىغان ئىچىملىك ماشىنىسىنى مەشغۇلات قىلىش ئاددىي ۋە قىزىقارلىق.","qol bilen aylanduridighan ichimlik mashinisini meshghulat qilish addiy we qiziqarliq."]],"手劲":[["他的手劲很大，能搬重物。","ئۇنىڭ قول كۈچى بەك چوڭ، ئېغىر نەرسىلەرنى يۆتكىيەلەيدۇ.","uning qol küchi bek chong, éghir nersilerni yötkiyeleydu."]],"打圆场":[["他打圆场化解了矛盾。","ئۇ ئارىلىشىپ زىددىيەتنى ھەل قىلدى.","u ariliship ziddiyetni hel qildi."]],"打场":[["秋天到了，大家开始打场粮食。","كۈز كەلدى، ھەممەيلەن ئاشلىق خامان تارتىشقا باشلىدى.","küz keldi, hemmeylen ashliq xaman tartishqa bashlidi."]],"打高尔夫球":[["他们去打高尔夫球了。","ئۇلار گولف توپ ئوينىغىلى كەتتى.","ular golf top oynighili ketti."]],"抓取程序":[["这个抓取程序能自动下载文件。","بۇ تۇتۇش پروگراممىسى ھۆججەتلەرنى ئاپتوماتىك چۈشۈرەلەيدۇ.","bu tutush programmisi höjjetlerni aptomatik chüshüreleydu."]],"抗锯齿":[["抗锯齿技术让图像更加清晰。","ئانتى-تىشلىق تېخنىكىسى سۈرەتنى تېخىمۇ ئېنىق قىلىدۇ.","anti-tishliq téxnikisi süretni téximu éniq qilidu."]],"抗灾":[["政府组织力量积极抗灾救灾。","ھۆكۈمەت كۈچلەرنى تەشكىللەپ ئاپەتكە قارشى تۇرۇش ۋە ئاپەتتىن قۇتقۇزۇش ئىشلىرىنى ئاكتىپ ئېلىپ باردى.","hökümet küchlerni teshkillep apetke qarshi turush we apettin qutquzush ishlirini aktip élip bardi."]],"招牌纸":[["这张招牌纸印满了广告。","بۇ ئاتاقلىق قەغەز ئېلان بىلەن تولدۇرۇلغان.","bu ataqliq qeghez élan bilen toldurulghan."]],"拳脚":[["他的拳脚功夫十分了得。","ئۇنىڭ مۇشت ۋە پۇت ماھارىتى ئىنتايىن يۇقىرى.","uning musht we put mahariti intayin yuqiri."]],"指挥者":[["指挥者需要精准控制节奏。","دىرىژور رىتىمنى ئېنىق كونترول قىلىشى كېرەك.","dirizhor ritimni éniq kontrol qilishi kérek."]],"持用":[["他持用传统方法制作。","ئۇ ئەنئەنىۋى ئۇسۇلدا ياسايدۇ.","u en'eniwi usulda yasaydu."]],"按兵不动":[["敌军按兵不动，等待时机。","دۈشمەن قوشۇنى ھەرىكەت قىلماي، پۇرسەت كۈتۈۋاتىدۇ.","düshmen qoshuni heriket qilmay, purset kütüwatidu."]],"捍卫者":[["他是正义的捍卫者。","ئۇ ھەققانىيەتنىڭ قوغدىغۇچىسى.","u heqqaniyetning qoghdighuchisi."]],"捕鱼":[["渔民在江中捕鱼。","بېلىقچى دەريادا بېلىق تۇتىدۇ.","béliqchi deryada béliq tutidu."]],"捧腹绝倒":[["他的表演让观众捧腹绝倒。","ئۇنىڭ نومۇرى تاماشىبىنلارنى كۈلۈپ يىقىلىدىغان دەرىجىدە كۈلدۈردى.","uning nomuri tamashibinlarni külüp yiqilidighan derijide küldürdi."]],"排笙":[["排笙是一种传统的民族乐器。","پەيشەڭ ئەنئەنىۋى مىللىي چالغۇ ئەسۋابىدۇر.","peysheng en'eniwi milliy chalghu eswabidur."]],"授意":[["他授意下属采取行动。","ئۇ قول ئاستىدىكىلەرگە ھەرىكەت قوللىنىشقا يوليورۇق بەردى.","u qol astidikilerge heriket qollinishqa yolyoruq berdi."]],"提列":[["名单上提列了所有候选人。","تىزىملىككە بارلىق نامزاتلار تىزىپ كۆرسىتىلدى.","tizimlikke barliq namzatlar tizip körsitildi."]],"挟天子以令天下":[["他挟天子以令天下，掌控全局。","ئۇ پادىشاھنى تۇتقۇن قىلىپ پۈتۈن دۇنياغا بۇيرۇق چۈشۈردى، پۈتۈن ۋەزىيەتنى كونترول قىلدى.","u padishahni tutqun qilip pütün dunyagha buyruq chüshürdi, pütün weziyetni kontrol qildi."]],"揭幕式":[["揭幕式在下午举行。","ئېچىلىش مۇراسىمى چۈشتىن كېيىن ئۆتكۈزۈلىدۇ.","échilish murasimi chüshtin kéyin ötküzülidu."]],"提起精神":[["他提起精神，开始认真工作。","ئۇ روھىنى كۆتۈرۈپ، ئەستايىدىل خىزمەت قىلىشقا باشلىدى.","u rohini kötürüp, estayidil xizmet qilishqa bashlidi."]],"抢滩":[["士兵们成功抢滩登陆，扭转了战局。","ئەسكەرلەر دېڭىز بويىغا مۇۋەپپەقىيەتلىك چىقىپ، ئۇرۇش ئەھۋالىنى ئۆزگەرتتى.","eskerler déngiz boyigha muweppeqiyetlik chiqip, urush ehwalini özgertti."]],"撒哈拉人":[["撒哈拉人适应了极端干旱的环境。","ساھارالىقلار ئەسكەرچىلىك قۇرغاقچىلىق مۇھىتىغا ماسلاشقان.","saharaliqlar eskerchilik qurghaqchiliq muhitigha maslashqan."]],"搭架子":[["搭架子需要工具。","ئىسكىلات قۇرۇش ئۈچۈن قورال كېرەك.","iskilat qurush üchün qoral kérek."]],"擦拭":[["她擦拭镜头，确保清晰成像。","ئۇ كامېرا لىنزىسىنى سۈرتۈپ، ئېنىق تەسۋىر ھاسىل قىلدى.","u kaméra linzisini sürtüp, éniq teswir hasil qildi."]],"攘诟":[["他忍受了攘诟。","ئۇ تىل-ئاھانەتلەرگە چىدىدى.","u til-ahanetlerge chididi."]],"搀假":[["这药里搀假了其他成分。","بۇ دورىغا باشقا تەركىبلەر ئارىلاشتۇرۇلغان.","bu dorigha bashqa terkibler arilashturulghan."]],"支取":[["可以从账户中支取现金。","ھېساباتتىن نەق پۇل ئالغىلى بولىدۇ.","hésabattin neq pul alghili bolidu."]],"故第":[["这座故第曾是家族的重要宅邸。","بۇ كونا ئۆي ئىلگىرى ئائىلىنىڭ مۇھىم تۇرالغۇسى ئىدى.","bu kona öy ilgiri ailining muhim turalghusi idi."]],"敌杀死":[["敌杀死是一种高效杀虫剂。","دۈشمەن-ئۆلتۈرۈش يۇقىرى ئۈنۈملۈك بىر خىل ھاشارات ئۆلتۈرگۈچتۇر.","düshmen-öltürüsh yuqiri ünümlük bir xil hasharat öltürgüchtur."]],"斯洛伐克":[["斯洛伐克位于欧洲中部。","سلوۋاكىيە ياۋروپانىڭ ئوتتۇرىسىدا جايلاشقان.","slowakiye yawropaning otturisida jaylashqan."]],"文具店":[["文具店里有各种精美的文具。","يازۇ-يۈز ئەسۋابلىرى دۇكىنىدا ھەر خىل نەپىس يازۇ-يۈز ئەسۋابلىرى بار.","yazu-yüz eswabliri dukinida her xil nepis yazu-yüz eswabliri bar."]],"文创产业":[["文创产业近年来发展迅速。","مەدەنىيەت ئىجادىيەت سانائىتى يېقىنقى يىللاردا تېز تەرەققىي قىلدى.","medeniyet ijadiyet sanaiti yéqinqi yillarda téz tereqqiy qildi."]],"断气":[["他最后断气前说了句话。","ئۇ ئاخىرقى نەپىسىنى ئۈزۈشتىن بۇرۇن بىر ئېغىز سۆزلىدى.","u axirqi nepisini üzüshtin burun bir éghiz sözlidi."]],"断港绝潢":[["这个港口彻底断港绝潢了。","بۇ پورت پۈتۈنلەي ئۈزۈلۈپ قالدى.","bu port pütünley üzülüp qaldi."]],"旁门":[["他误入了旁门左道。","ئۇ خاتا يولغا كىرىپ قالدى.","u xata yolgha kirip qaldi."]],"旬阳":[["旬阳位于陕西省南部。","شۈنياڭ شەنشى ئۆلكىسىنىڭ جەنۇبىدا جايلاشقان.","shünyang shenshi ölkisining jenubida jaylashqan."]],"易拉宝":[["展会用了易拉宝展示。","كۆرگەزمىدە ئاسان كۆتۈرۈلىدىغان لافتا ئىشلىتىلدى.","körgezmide asan kötürülidighan lafta ishlitildi."]],"春灌":[["春灌是春季的重要灌溉措施。","باھار سۇغىرىشى باھار مەۋسۇمىنىڭ مۇھىم سۇغىرىش تەدبىرى.","bahar sughirishi bahar mewsumining muhim sughirish tedbiri."]],"星历":[["他查阅星历，确认今晚的星象对出行有利。","ئۇ يۇلتۇزلار كالېندارىنى تەكشۈرۈپ، بۈگۈن كېچىدىكى يۇلتۇزلار ھالىتىنىڭ سەپەرگە پايدىلىق ئىكەنلىكىنى جەزملەشتۈردى.","u yultuzlar kaléndarini tekshürüp, bügün kéchidiki yultuzlar halitining seperge paydiliq ikenlikini jezmleshtürdi."]],"昆汀·塔伦蒂诺":[["昆汀·塔伦蒂诺的影片很受欢迎。","قۇنتىن تارانتىنونىڭ فىلىملىرى ئىنتايىن ئالقىشقا ئېرىشكەن.","quntin tarantinoning filimliri intayin alqishqa érishken."]],"昌江区":[["昌江区位于江西省北部。","چاڭجياڭ رايونى جياڭشى ئۆلكىسىنىڭ شىمالىدا جايلاشقان.","changjyang rayoni jyangshi ölkisining shimalida jaylashqan."]],"景洪市":[["景洪市是傣族的主要聚居地。","جىڭخۇڭ شەھىرى دەيلارنىڭ ئاساسلىق توپلىشىپ ئولتۇراقلاشقان جايى.","jingxung shehiri deylarning asasliq topliship olturaqlashqan jayi."]],"暴击":[["这次攻击造成了暴击。","بۇ قېتىملىق ھۇجۇم ئالاھىدە زەربە پەيدا قىلدى.","bu qétimliq hujum alahide zerbe peyda qildi."]],"暴死":[["那匹马在奔跑中突然暴死。","ئۇ ئات يۈگۈرۈش جەريانىدا تۇيۇقسىز ئۆلۈپ چۈشتى.","u at yügürüsh jeryanida tuyuqsiz ölüp chüshti."]],"暗疾":[["他患有长期暗疾，从未告诉别人。","ئۇ ئۇزۇن مۇددەتلىك يوشۇرۇن كېسەلگە گىرىپتار بولغان، ھېچكىمگە ئېيتقان ئەمەس.","u uzun muddetlik yoshurun késelge giriptar bolghan, héchkimge éytqan emes."]],"书亭":[["书亭是供人阅读的小建筑。","كىتابخانا كىشىلەرنىڭ ئوقۇشى ئۈچۈن قۇرۇلغان كىچىك بىنا.","kitabxana kishilerning oqushi üchün qurulghan kichik bina."]],"书札":[["书札是古代文人之间的通信。","خەت-چەك قەدىمكى زامان ئەدىبلىرى ئارىسىدىكى ئالاقە ئىدى.","xet-chek qedimki zaman edibliri arisidiki alaqe idi."]],"有数":[["他对情况很有数。","ئۇ ئەھۋالنى ئېنىق بىلىدۇ.","u ehwalni éniq bilidu."]],"会不会":[["你明天会不会来找我？","سەن ئەتە مېنى ئىزدەپ كېلەمسەن؟","sen ete méni izdep kélemsen?"]],"会审":[["法官会审了这起复杂案件。","سوتچى بۇ مۇرەككەپ دەۋانى بىرلىكتە سوت قىلدى.","sotchi bu murekkep dewani birlikte sot qildi."]],"有产者":[["有产者往往在社会中占据优势地位。","مۈلۈكدارلار جەمئىيەتتە كۆپىنچە ئۈستۈنلۈك ئورۇننى ئىگىلەيدۇ.","mülükdarlar jem'iyette köpinche üstünlük orunni igileydu."]],"朔望":[["朔望指的是新月和满月的时期。","شوۋۋاڭ يېڭى ئاي ۋە تولۇن ئاي مەزگىلىنى كۆرسىتىدۇ.","showwang yéngi ay we tolun ay mezgilini körsitidu."]],"朔望潮":[["朔望潮与月相变化有关。","شوۋۋاڭ ئوقيانى ئاي فازىسىنىڭ ئۆزگىرىشى بىلەن مۇناسىۋەتلىك.","showwang oqyani ay fazisining özgirishi bilen munasiwetlik."]],"木夯":[["古代建筑常用木夯来夯实地面。","قەدىمكى بىنالاردا كۆپىنچە ياغاچ توڭگۇزغۇچ ئىشلىتىپ زېمىننى پۇختىلايدۇ.","qedimki binalarda köpinche yaghach tongguzghuch ishlitip zéminni puxtilaydu."]],"有能力":[["他有能力完成这项艰巨的任务。","ئۇ بۇ مۈشكۈل ۋەزىپىنى ئورۇنداشقا قادىر.","u bu müshkül wezipini orundashqa qadir."]],"木薯":[["木薯是一种重要的热带作物。","ياغاچ كاساۋا مۇھىم تروپىك زىرائىتى.","yaghach kasawa muhim tropik ziraiti."]],"本征值":[["本征值在数学中具有重要意义。","ئاساسىي خاسلىق قىممىتى ماتېماتىكىدا مۇھىم ئەھمىيەتكە ئىگە.","asasiy xasliq qimmiti matématikida muhim ehmiyetke ige."]],"杜口":[["他因害怕而杜口不言。","ئۇ قورققانلىقى ئۈچۈن ئاغزىنى ئاچمىدى.","u qorqqanliqi üchün aghzini achmidi."]],"东巴文化":[["东巴文化是纳西族的独特文化。","دۇڭبا مەدەنىيىتى ناخشى مىللىتىنىڭ ئۆزگىچە مەدەنىيىتى.","dungba medeniyiti naxshi millitining özgiche medeniyiti."]],"东北平原":[["东北平原是中国最大的平原。","شەرقىي شىمال تۈزلەڭلىكى جۇڭگونىڭ ئەڭ چوڭ تۈزلەڭلىكىدۇر.","sherqiy shimal tüzlengliki junggoning eng chong tüzlenglikidur."]],"东西湖区":[["东西湖区位于武汉市西北部。","دۇڭشىخۇ رايونى ۋۇخەن شەھىرىنىڭ شىمالىي غەربىي قىسمىدا جايلاشقان.","dungshixu rayoni wuxen shehirining shimaliy gherbiy qismida jaylashqan."]],"东港区":[["东港区发展迅速，商业繁荣。","دۇڭگاڭ رايونى تېز تەرەققىي قىلماقتا، سودىسى گۈللەنمەكتە.","dunggang rayoni téz tereqqiy qilmaqta, sodisi güllenmekte."]],"板车":[["板车结构简单，容易维修。","تاختا ھارۋا قۇرۇلمىسى ئاددىي، رېمونت قىلىش ئاسان.","taxta harwa qurulmisi addiy, rémont qilish asan."]],"李约瑟":[["李约瑟是英国著名的中国历史学家。","لى يوسېف ئەنگلىيەلىك داڭلىق جۇڭگو تارىخچىسى.","li yoséf engliyelik dangliq junggo tarixchisi."]],"林纾":[["林纾是晚清时期的重要翻译家。","لىن شۇ چىڭ سۇلالىسىنىڭ ئاخىرقى دەۋرىدىكى مۇھىم تەرجىمان.","lin shu ching sulalisining axirqi dewridiki muhim terjiman."]],"柔软剂":[["这款柔软剂能让衣物更舒适。","بۇ يۇمشاتقۇچ كىيىمنى تېخىمۇ راھەت قىلالايدۇ.","bu yumshatquch kiyimni téximu rahet qilalaydu."]],"架二郎腿":[["他习惯性地架二郎腿，显得十分随意。","ئۇ ئادەتلىنىپ پۇتىنى پۇتىغا ئېلىپ ئولتۇرىدۇ، بەك ئەركىن كۆرۈنىدۇ.","u adetlinip putini putigha élip olturidu, bek erkin körünidu."]],"格调":[["格调指事物的风格与品味。","ئۇسلۇب ئىشلارنىڭ ئۇسلۇبى ۋە زەوقىنى كۆرسىتىدۇ.","uslub ishlarning uslubi we zeoqini körsitidu."]],"果子冻":[["果子冻是一种水果果冻。","مېۋە مۇراببوسى بىر خىل مېۋە مۇراببوسى.","méwe murabbosi bir xil méwe murabbosi."]],"梁木":[["梁木是建筑中用于支撑屋顶的木材。","لياڭ ياغىچى بىناكارلىقتا ئۆگزىنى تىرەش ئۈچۈن ئىشلىتىلىدىغان ياغاچ.","lyang yaghichi binakarliqta ögzini tiresh üchün ishlitilidighan yaghach."]],"梅里美":[["梅里美是法国著名的小说家。","Mérimée bolsa فرانسىيەنىڭ داڭلىق رومانچىسى.","Mérimée bolsa fransiyening dangliq romanchisi."]],"梗图":[["梗图是网络文化中流行的图片模板。","گېڭتۇ ئىنتېرنېت مەدەنىيىتىدە ئومۇملاشقان رەسىم قېلىپى.","géngtu intérnét medeniyitide omumlashqan resim qélipi."]],"𬂩提":[["他𬂩提了会议的重要事项。","ئۇ يىغىننىڭ مۇھىم مەسىلىلىرىنى تىلغا ئالدى.","u yighinning muhim mesililirini tilgha aldi."]],"梵哑铃":[["梵哑铃是传统乐器。","فەنزە سىكىپكا ئەنئەنىۋى چالغۇ.","fenze sikipka en'eniwi chalghu."]],"棉兰":[["棉兰是印度尼西亚的一个港口城市。","مېدان ئىندونېزىيەدىكى بىر پورت شەھىرى.","médan indonéziyediki bir port shehiri."]],"棺椁":[["棺椁是古代用于盛放尸体的双层容器。","قوش قەۋەتلىك تابۇت قەدىمكى زاماندا جەسەتنى سېلىشقا ئىشلىتىلگەن قوش قەۋەتلىك ساۋۇت.","qosh qewetlik tabut qedimki zamanda jesetni sélishqa ishlitilgen qosh qewetlik sawut."]],"棕草鹛":[["棕草鹛常藏身于草丛中。","قوڭۇر چۆپ شاۋمېي كۆپىنچە چۆپلەر ئارىسىدا يوشۇرۇنىدۇ.","qongur chöp shawméy köpinche chöpler arisida yoshurunidu."]],"棕褐短翅莺":[["棕褐短翅莺的翅膀较短。","قوڭۇر قوڭۇر قىسقا قاناتلىق چىۋىقنىڭ قاناتلىرى بىر قەدەر قىسقا.","qongur qongur qisqa qanatliq chiwiqning qanatliri bir qeder qisqa."]],"条陈":[["他向朝廷提交了一份条陈。","ئۇ ھۆكۈمەتكە بىر تىزىملىك ئەرزىنى سۇندى.","u hökümetke bir tizimlik erzini sundi."]],"极限运动":[["他喜欢挑战各种极限运动。","ئۇ تۈرلۈك قۇتۇپ چەكلىك تەنھەرىكەتلىرىگە خىرىس قىلىشنى ياخشى كۆرىدۇ.","u türlük qutup cheklik tenheriketlirige xiris qilishni yaxshi köridu."]],"构型":[["这种构型在工程领域很常见。","بۇ تىپتىكى قۇرۇلما ئىنژېنېرلىق ساھەسىدە ئىنتايىن ئومۇمىي.","bu tiptiki qurulma inzhénérliq saheside intayin omumiy."]],"条案":[["条案是传统家具的一种。","ئۇزۇن تاختىلىق ئۈستەل ئەنئەنىۋى ئۆي ئەسۋابلىرىنىڭ بىر تۈرىدۇر.","uzun taxtiliq üstel en'eniwi öy eswablirining bir türidur."]],"条条大路通罗马":[["条条大路通罗马，殊途同归。","بارلىق يوللار رىمغا ئېلىپ بارىدۇ، ئوخشىمىغان يوللار ئوخشاش نەتىجىگە يېتىپ بارىدۇ.","barliq yollar rimgha élip baridu, oxshimighan yollar oxshash netijige yétip baridu."]],"楞严":[["《楞严经》是佛教重要经典。","«لېڭيەن جىڭ» بۇددا دىنىنىڭ مۇھىم كلاسسىك ئەسىرىدۇر.","«léngyen jing» budda dinining muhim klassik esiridur."]],"标准杆":[["标准杆是高尔夫球场的基本计分单位。","ئۆلچەملىك تاياق گولف مەيدانىنىڭ ئاساسىي نومۇر ھېسابلاش بىرلىكى.","ölchemlik tayaq golf meydanining asasiy nomur hésablash birliki."]],"机械能":[["机械能可以转化为热能。","مېخانىكىلىق ئېنېرگىيە ئىسسىقلىق ئېنېرگىيەسىگە ئايلانىدۇ.","méxanikiliq énérgiye issiqliq énérgiyesige aylanidu."]],"横山":[["横山风景优美。","كۆندىلەڭ تاغنىڭ مەنزىرىسى گۈزەل.","köndileng taghning menzirisi güzel."]],"栏架":[["栏架支撑着整个结构。","توسما رامكا پۈتۈن قۇرۇلمىنى تىرەيدۇ.","tosma ramka pütün qurulmini tireydu."]],"歌仔戏":[["闽南地区流行着一种叫歌仔戏的传统戏曲。","جەنۇبىي فۇجيەن رايونىدا گېزى ئويۇنى دېگەن ئەنئەنىۋى ئويۇن تارقالغان.","jenubiy fujyen rayonida gézi oyuni dégen en'eniwi oyun tarqalghan."]],"欧洲防风":[["欧洲防风草是常见的蔬菜品种。","ياۋروپا پارسىنېپى ئادەتتىكى كۆكتات تۈرىدۇر.","yawropa parsinépi adettiki köktat türidur."]],"欧美":[["欧美文化对世界影响深远。","ياۋروپا-ئامېرىكا مەدەنىيىتى دۇنياغا چوڭقۇر تەسىر كۆرسەتكەن.","yawropa-amérika medeniyiti dunyagha chongqur tesir körsetken."]],"武威市":[["武威市以凉州文化闻名。","ۋۇۋېي شەھىرى لياڭجۇ مەدەنىيىتى بىلەن داڭلىق.","wuwéy shehiri lyangju medeniyiti bilen dangliq."]],"毛织运动衫":[["这件毛织运动衫很柔软。","بۇ يۇڭ توقۇلما تەنتەربىيە كۆڭلىكى ناھايىتى يۇمشاق.","bu yung toqulma tenterbiye köngliki nahayiti yumshaq."]],"毛遂":[["毛遂自荐的故事广为流传。","خام سۈيى ئۆزىنى تەۋسىيە قىلغان ھېكايە كەڭ تارقالغان.","xam süyi özini tewsiye qilghan hékaye keng tarqalghan."]],"毛霉菌病":[["毛霉菌病具有传染性。","خام موكور مېخۇت كېسىلى يۇقۇملۇق.","xam mokor méxut késili yuqumluq."]],"殷实":[["公司财务状况殷实稳定。","شىركەتنىڭ مالىيە ئەھۋالى مول ۋە مۇقىم.","shirketning maliye ehwali mol we muqim."]],"氰苷":[["氰苷存在于多种植物中，具有毒性。","سىيان گلىكوزىد نۇرغۇن ئۆسۈملۈكلەردە مەۋجۇت بولۇپ، زەھەرلىك خۇسۇسىيەتكە ئىگە.","siyan glikozid nurghun ösümlüklerde mewjut bolup, zeherlik xususiyetke ige."]],"水上芭蕾":[["水上芭蕾表演充满艺术美感。","سۇ ئۈستى بالېت ئويۇنى سەنئەت گۈزەللىكىگە تولغان.","su üsti balét oyuni sen'et güzellikige tolghan."]],"水产业":[["水产业是沿海经济支柱。","سۇ مەھسۇلاتلىرى سانائىتى دېڭىز بويى ئىقتىسادىنىڭ تۈۋرۈكى.","su mehsulatliri sanaiti déngiz boyi iqtisadining tüwrüki."]],"水系":[["这个水系非常复杂。","بۇ سۇ سىستېمىسى ناھايىتى مۇرەككەپ.","bu su sistémisi nahayiti murekkep."]],"水蛭素":[["水蛭素具有抗凝血作用。","زۇلۇك ماددىسى قان ئۇيۇشۇشنىڭ ئالدىنى ئېلىش رولىغا ئىگە.","zuluk maddisi qan uyushushning aldini élish roligha ige."]],"永新县":[["永新县以丰富的旅游资源闻名。","يۇڭشىن ناھىيىسى مول ساياھەت بايلىقلىرى بىلەن تونۇلغان.","yungshin nahiyisi mol sayahet bayliqliri bilen tonulghan."]],"永丰县":[["永丰县是江西省的一个县。","يۇڭفېڭ ناھىيىسى جياڭشى ئۆلكىسىدىكى بىر ناھىيە.","yungféng nahiyisi jyangshi ölkisidiki bir nahiye."]],"永泰县":[["永泰县拥有多处国家级文物保护单位。","يۇڭتەي ناھىيىسىدە دۆلەت دەرىجىلىك مەدەنىيەت يادىكارلىقلىرىنى قوغداش ئورنى كۆپ.","yungtey nahiyiside dölet derijilik medeniyet yadikarliqlirini qoghdash orni köp."]],"永诀式":[["这种永诀式告别令人伤感。","بۇ خىل مەڭگۈلۈك خوشلاشش كىشىنى قايغۇغا سالىدۇ.","bu xil menggülük xoshlashsh kishini qayghugha salidu."]],"汗珠子":[["他的额头上布满了汗珠子。","ئۇنىڭ پېشانىسى تەر تامچىلىرى بىلەن قاپلانغان.","uning péshanisi ter tamchiliri bilen qaplanghan."]],"氽汤":[["氽汤是一种简单的烹饪方法。","چۆكۈرۈپ پىشۇرۇش ئۇسۇلى بىر خىل ئاددىي تاماق ئېتىش ئۇسۇلى.","chökürüp pishurush usuli bir xil addiy tamaq étish usuli."]],"沙皇俄国":[["沙皇俄国在历史上影响深远。","چار رۇسىيەسى تارىختا چوڭقۇر تەسىرگە ئىگە.","char rusiyesi tarixta chongqur tesirge ige."]],"河豚":[["河豚是一种有毒的鱼类。","دەريا چوشقىسى زەھەرلىك بىر خىل بېلىق.","derya choshqisi zeherlik bir xil béliq."]],"波森莓":[["波森莓是一种常见的水果。","بويزېنبېرى ئادەتتىكى بىر مېۋە تۈرى.","boyzénbéri adettiki bir méwe türi."]],"波罗蜜":[["波罗蜜是一种热带水果。","پارامىت ئاسمان جەنۇبىي ئامېرىكىدىكى قەدىمكى بىر خىل مېۋە.","paramit asman jenubiy amérikidiki qedimki bir xil méwe."]],"波恩":[["波恩是德国的一座历史文化名城。","بون گېرمانىيەدىكى بىر تارىخىي مەدەنىيەت شەھىرىدۇر.","bon gérmaniyediki bir tarixiy medeniyet shehiridur."]],"法轮大法":[["法轮大法的教义被广泛传播。","فالۇن دادا تەلىماتى كەڭ تارقالغان.","falun dada telimati keng tarqalghan."]],"法眼":[["法眼能洞察事物的本质与真相。","قانۇن كۆزى ئەشيالارنىڭ ماھىيىتى ۋە ھەقىقىتىنى كۆرەلەيدۇ.","qanun közi eshyalarning mahiyiti we heqiqitini köreleydu."]],"法属波利尼西亚":[["法属波利尼西亚是法国的海外领地。","فىرانسىيەگە تەۋە پولىنېزىيە فىرانسىيەنىڭ چەتئەلدىكى زېمىنىدۇر.","firansiyege tewe polinéziye firansiyening chet'eldiki zéminidur."]],"泄私愤":[["他借工作泄私愤。","ئۇ خىزمەتتىن پايدىلىنىپ شەخسىي غەزىپىنى چىقىرىدۇ.","u xizmettin paydilinip shexsiy ghezipini chiqiridu."]],"泰米尔猛虎组织":[["泰米尔猛虎组织是斯里兰卡的武装团体。","تامىل قاپلان تەشكىلاتى سىرىلانكىنىڭ قوراللىق گۇرۇھىدۇر.","tamil qaplan teshkilati sirilankining qoralliq guruhidur."]],"浣熊":[["浣熊喜欢吃坚果和水果。","راكۇن يېڭىق يېمىشلىك ۋە مېۋىلەرنى ياخشى كۆرىدۇ.","rakun yéngiq yémishlik we méwilerni yaxshi köridu."]],"海晏县":[["海晏县位于青海省的北部。","خەييەن ناھىيىسى چىڭخەي ئۆلكىسىنىڭ شىمالىي قىسمىدا.","xeyyen nahiyisi chingxey ölkisining shimaliy qismida."]],"海瑞":[["海瑞是明朝的清官。","خەيرۇي مىڭ سۇلالىسىنىڭ پاك ئەمەلدارى ئىدى.","xeyruy ming sulalisining pak emeldari idi."]],"海上花列传":[["《海上花列传》是经典小说。","«دېڭىزدىكى گۈللەر تەزكىرىسى» كلاسسىك رومان.","«déngizdiki güller tezkirisi» klassik roman."]],"浸湿":[["鞋子被雨水浸湿变重。","ئاياغ يامغۇردا ھۆل بولۇپ ئېغىرلاشتى.","ayagh yamghurda höl bolup éghirlashti."]],"消夏":[["夏天傍晚乘凉，正是消夏的好时机。","ياز كۈنلىرى كەچقۇرۇن سەيلە قىلىپ سالقىنلىشىش دەل يازنى ئۆتكۈزۈشنىڭ ياخشى پۇرسىتى.","yaz künliri kechqurun seyle qilip salqinlishish del yazni ötküzüshning yaxshi pursiti."]],"深恶痛绝":[["他深恶痛绝这种虚伪行为。","ئۇ بۇنداق ساختىپەزلىك قىلمىشلىرىدىن چوڭقۇر نەپرەتلىنىدۇ.","u bundaq saxtipezlik qilmishliridin chongqur nepretlinidu."]],"淅川县":[["淅川县以独特的自然风光闻名。","شىچۇەن ناھىيىسى ئۆزىگە خاس تەبىئىي مەنزىرىسى بىلەن داڭلىق.","shichuen nahiyisi özige xas tebiiy menzirisi bilen dangliq."]],"海神":[["海神掌管着海洋的安宁。","دېڭىز ئىلاھى ئوكياننىڭ تىنچلىقىنى باشقۇرىدۇ.","déngiz ilahi okyanning tinchliqini bashquridu."]],"淮南子":[["《淮南子》是古代重要典籍。","«جۈنەنزى» قەدىمكى زاماندىكى مۇھىم كلاسسىك ئەسەر.","«jünenzi» qedimki zamandiki muhim klassik eser."]],"淮安市":[["淮安市位于江苏省北部。","خۇەيئەن شەھىرى جياڭسۇ ئۆلكىسىنىڭ شىمالىدا جايلاشقان.","xuey'en shehiri jyangsu ölkisining shimalida jaylashqan."]],"凄惋":[["她的眼神中充满了凄惋，让人心生怜悯。","ئۇنىڭ كۆزلىرىدە قايغۇ تولۇپ، كىشىلەرنى رەھىم قىلدۇردى.","uning közliride qayghu tolup, kishilerni rehim qildurdi."]],"湘江":[["湘江是湖南省的主要河流。","شياڭجياڭ دەرياسى خۇنەن ئۆلكىسىنىڭ ئاساسلىق دەرياسى.","shyangjyang deryasi xunen ölkisining asasliq deryasi."]],"汤加里罗":[["汤加里罗火山喷发了。","تونگارىرو يانار تېغى ئوت ئالدى.","tongariro yanar téghi ot aldi."]],"滋补品":[["他买了许多滋补品进补。","ئۇ نۇرغۇن ئوزۇقلۇق تولۇقلىغۇچى ماددىلارنى سېتىۋېلىپ بەدەن تولۇقلىدى.","u nurghun ozuqluq toluqlighuchi maddilarni sétiwélip beden toluqlidi."]],"汉台":[["汉台是汉代的皇家园林遗址。","خەنتەي خەن سۇلالىسى دەۋرىدىكى پادىشاھ باغچىسىنىڭ خارابىسىدۇر.","xentey xen sulalisi dewridiki padishah baghchisining xarabisidur."]],"涨跌幅限制":[["该股票设置了10%的涨跌幅限制。","بۇ پاي چېكىگە 10 پىرسەنت ئۆسۈش-چۈشۈش چېكى قويۇلغان.","bu pay chékige 10 pirsent ösüsh-chüshüsh chéki qoyulghan."]],"渔汛":[["渔汛显示鱼群即将到达。","بېلىق توپى بېلىق توپىنىڭ يېقىنلاپ كېلىۋاتقانلىقىنى كۆرسىتىدۇ.","béliq topi béliq topining yéqinlap kéliwatqanliqini körsitidu."]],"瀍水":[["瀍水是流经洛阳的一条河流。","چەنشۇي لوياڭدىن ئېقىپ ئۆتىدىغان بىر دەريا.","chenshuy loyangdin éqip ötidighan bir derya."]],"灌输":[["老师向学生灌输知识。","ئوقۇتقۇچى ئوقۇغۇچىلارغا بىلىم قۇيدى.","oqutquchi oqughuchilargha bilim quydi."]],"灞桥":[["灞桥是长安通往东方的重要通道。","باچياۋ كوۋىرى چاڭئەندىن شەرققە بارىدىغان مۇھىم يول ئىدى.","bachyaw kowiri chang'endin sherqqe baridighan muhim yol idi."]],"泸县":[["泸县历史悠久。","لۇشيەن ناھىيىسىنىڭ ئۇزۇن تارىخى بار.","lushyen nahiyisining uzun tarixi bar."]],"泸西":[["泸西是一个旅游胜地。","لۇشى مەنزىرە رايونى.","lushi menzire rayoni."]],"炳蔚":[["学术成果炳蔚可观。","ئىلمىي نەتىجىلەر مول ۋە كۆرۈنەرلىك.","ilmiy netijiler mol we körünerlik."]],"乌兰夫":[["乌兰夫是中国共产党的早期领导人。","ئۇلانفۇ جۇڭگو كوممۇنىستىك پارتىيەسىنىڭ دەسلەپكى رەھبەرلىرىنىڭ بىرىدۇر.","ulanfu junggo kommunistik partiyesining deslepki rehberlirining biridur."]],"乌西亚":[["乌西亚是土耳其的一个省份。","ئۇسىيا تۈركىيەدىكى بىر ئۆلكىدۇر.","usiya türkiyediki bir ölkidur."]],"乌马河区":[["乌马河区是乌马河沿岸的一个行政区。","ئۇما دەريا رايونى ئۇما دەريا بويىدىكى بىر مەمۇرىي رايونتۇر.","uma derya rayoni uma derya boyidiki bir memuriy rayontur."]],"乌当":[["乌当是贵阳的一个区。","ئۇداڭ گۈيياڭدىكى بىر رايون.","udang güyyangdiki bir rayon."]],"烤面包":[["烤面包的香味令人垂涎。","قورۇلغان بولكا پۇرىقى كىشىنىڭ ئاغزىنى سۇندۇرىدۇ.","qorulghan bolka puriqi kishining aghzini sunduridu."]],"无人能及":[["他的才华无人能及。","ئۇنىڭ تالانتىغا ھېچكىم يېتەلمەيدۇ.","uning talantigha héchkim yételmeydu."]],"烤火":[["他坐在火堆旁烤火取暖。","ئۇ ئوت يېنىدا ئولتۇرۇپ ئىسسىنىۋاتىدۇ.","u ot yénida olturup issiniwatidu."]],"无性":[["这种植物具有无性繁殖的特点。","بۇ خىل ئۆسۈملۈك جىنسسىز كۆپىيىش ئالاھىدىلىكىگە ئىگە.","bu xil ösümlük jinssiz köpiyish alahidilikige ige."]],"无愧":[["他对得起自己的良心，问心无愧。","ئۇ ئۆز ۋىجدانىنىڭ ئالدىدا پاك، ۋىجدانى ئەيىبسىز.","u öz wijdanining aldida pak, wijdani eyibsiz."]],"无货":[["商店今天无货，无法购买。","دۇكاندا بۈگۈن مال يوق، سېتىۋالغىلى بولمايدۇ.","dukanda bügün mal yoq, sétiwalghili bolmaydu."]],"烟卷儿":[["他抽的烟卷儿都是自己卷的。","ئۇ چېكىدىغان تاماكىلارنىڭ ھەممىسىنى ئۆزى ئورايدۇ.","u chékidighan tamakilarning hemmisini özi oraydu."]],"熟识":[["他们从小一起长大，彼此非常熟识。","ئۇلار كىچىكىدىن بىللە چوڭ بولغان، بىر-بىرىنى ئىنتايىن ياخشى تونۇيدۇ.","ular kichikidin bille chong bolghan, bir-birini intayin yaxshi tonuydu."]],"牛市":[["股市今天进入了牛市。","پاي بازىرى بۈگۈن كالا بازىرىغا كىردى.","pay baziri bügün kala bazirigha kirdi."]],"版式":[["杂志的版式很精美。","ژۇرنالنىڭ بەت ئورۇنلاشتۇرۇلۇشى ناھايىتى گۈزەل.","zhurnalning bet orunlashturulushi nahayiti güzel."]],"燕隼":[["燕隼是一种猛禽。","يەنسۈن يىرتقۇچ قۇشتۇر.","yensün yirtquch qushtur."]],"狎妓冶游":[["他沉迷于狎妓冶游，荒废了学业。","ئۇ پاھىشىۋازلىق ۋە ئويۇن-تاماشىغا بېرىلىپ، ئوقۇشىنى تاشلىدى.","u pahishiwazliq we oyun-tamashigha bérilip, oqushini tashlidi."]],"猴头菇":[["猴头菇是一种美味的野生菌类。","مايمۇن بېشى گۆمبىسى بىر خىل مەززىلىك ياۋا زەمبۇرۇغ تۈرى.","maymun béshi gömbisi bir xil mezzilik yawa zemburugh türi."]],"玉兰":[["玉兰花开得洁白无瑕。","يۈلەن گۈلى پاك ۋە ئەيىبسىز ھالدا ئېچىلغان.","yülen güli pak we eyibsiz halda échilghan."]],"玉田":[["玉田是河北省的一个农业大县。","يۈتيەن خېبېي ئۆلكىسىدىكى بىر يېزا ئىگىلىك چوڭ ناھىيىسى.","yütyen xébéy ölkisidiki bir yéza igilik chong nahiyisi."]],"玻璃杯":[["请用玻璃杯喝水。","ئەينەك چەينەك بىلەن سۇ ئىچىڭ.","eynek cheynek bilen su iching."]],"玩儿命":[["他玩儿命工作，从不休息。","ئۇ جان-دىلى بىلەن ئىشلەيدۇ، ھەرگىز دەم ئالمايدۇ.","u jan-dili bilen ishleydu, hergiz dem almaydu."]],"玩乐":[["周末的玩乐让他身心放松。","ھەپتە ئاخىرىدىكى ئويۇن-كۈلكىلەر ئۇنىڭ بەدەن-روھىنى بوشاشتۇردى.","hepte axiridiki oyun-külkiler uning beden-rohini boshashturdi."]],"瓷实":[["瓷实说明质地坚固。","فارفورنىڭ زىچلىقى ماتېرىيالنىڭ مۇستەھكەملىكىنى كۆرسىتىدۇ.","farforning zichliqi matériyalning mustehkemlikini körsitidu."]],"生殖器官":[["生殖器官在生物发育中起关键作用。","كۆپىيىش ئەزالىرى جانلىقلارنىڭ تەرەققىياتىدا ھالقىلىق رول ئوينايدۇ.","köpiyish ezaliri janliqlarning tereqqiyatida halqiliq rol oynaydu."]],"申通":[["申通快递服务很便捷。","شېنتوڭ تېز يوللاش مۇلازىمىتى ئىنتايىن قولايلىق.","shéntong téz yollash mulazimiti intayin qolayliq."]],"留尼汪":[["留尼汪以独特的火山景观闻名。","رېئونىيون ئۆزگىچە يانار تاغ مەنزىرىسى بىلەن تونۇلغان.","réoniyon özgiche yanar tagh menzirisi bilen tonulghan."]],"留有余地":[["谈判时要留有余地，别太强硬。","سۆھبەتتە ئورۇن قالدۇرۇڭ، بەك قاتتىق بولماڭ.","söhbette orun qaldurung, bek qattiq bolmang."]],"产后":[["产后恢复很重要。","تۇغۇتتىن كېيىن ئەسلىگە كېلىش ناھايىتى مۇھىم.","tughuttin kéyin eslige kélish nahayiti muhim."]],"癞皮狗":[["他就像个癞皮狗一样。","ئۇ خۇددى يالاڭئىتتىن كۈچۈكىدەك.","u xuddi yalang'ittin küchükidek."]],"发射场":[["发射场位于沙漠的偏远地区。","ئاتىش مەيدانى چۆلدىكى چەت يېرىدە جايلاشقان.","atish meydani chöldiki chet yéride jaylashqan."]],"发射机":[["无线发射机信号覆盖范围广。","سىمسىز ئاتقۇچ ئاپپاراتنىڭ سىگنالى قاپلاش دائىرىسى كەڭ.","simsiz atquch apparatning signali qaplash dairisi keng."]],"疑问代词":[["‘谁’‘什么’都是疑问代词。","«كىم» ۋە «نېمە» ھەر ئىككىسى سوئال ئالماشلىرىدۇر.","«kim» we «néme» her ikkisi soal almashliridur."]],"当机":[["当机立断，才能抓住机会。","پۇرسەتنى تۇتۇش ئۈچۈن دەرھال قارار چىقىرىش كېرەك.","pursetni tutush üchün derhal qarar chiqirish kérek."]],"当空":[["烈日当空，气温非常高。","قۇياش بەكمۇ قىزىق، ھاۋا تېمپېراتۇرىسى ئىنتايىن يۇقىرى.","quyash bekmu qiziq, hawa témpératurisi intayin yuqiri."]],"异义":[["这两个词有异义。","بۇ ئىككى سۆزنىڭ مەنىسى ئوخشاش ئەمەس.","bu ikki sözning menisi oxshash emes."]],"白顶鹀":[["白顶鹀的头顶有一块白色斑纹。","ئاق باشلىق تۇرغاينىڭ بېشىنىڭ ئۈستىدە بىر پارچە ئاق تەڭكە بار.","aq bashliq turghayning béshining üstide bir parche aq tengke bar."]],"白颊山鹧鸪":[["白颊山鹧鸪生活在山区。","ئاق ياقىلىق تاغ كەكلىكى تاغلىق رايونلاردا ياشايدۇ.","aq yaqiliq tagh kekliki taghliq rayonlarda yashaydu."]],"白鹤":[["白鹤在湿地中翩翩起舞。","ئاق تۇرنا سۇلۇق يەرلەردە ئۇسسۇل ئوينىغاندەك ئۇچىدۇ.","aq turna suluq yerlerde ussul oynighandek uchidu."]],"百病":[["他长期患有百病，身体非常虚弱。","ئۇ ئۇزۇن مۇددەت يۈز خىل كېسەلگە گىرىپتار بولۇپ، بەدىنى ئىنتايىن ئاجىز.","u uzun muddet yüz xil késelge giriptar bolup, bedini intayin ajiz."]],"礁湖星云":[["礁湖星云是宇宙中最著名的星云之一。","رىف كۆلى نېبۇلاسى ئالەمدىكى ئەڭ داڭلىق نېبۇلاسلارنىڭ بىرى.","rif köli nébulasi alemdiki eng dangliq nébulaslarning biri."]],"砍头":[["古代有砍头这种刑罚。","قەدىمدە باش چېپىش جازاسى بار ئىدى.","qedimde bash chépish jazasi bar idi."]],"石鼓文":[["石鼓文是中国最早的刻石文字。","شىگۇ يېزىقى جۇڭگودىكى ئەڭ قەدىمكى تاشقا ئويۇلغان يېزىق.","shigu yéziqi junggodiki eng qedimki tashqa oyulghan yéziq."]],"笨伯":[["这位笨伯总是帮倒忙。","بۇ ئەخمەق ھەمىشە ئىشنى بۇزىدۇ.","bu exmeq hemishe ishni buzidu."]],"绍兴":[["绍兴是中国著名的历史文化名城。","شاۋشىڭ جۇڭگونىڭ مەشھۇر تارىخىي-مەدەنىي شەھىرى.","shawshing junggoning meshhur tarixiy-medeniy shehiri."]],"索尔仁尼琴":[["索尔仁尼琴是诺贝尔文学奖得主。","سولجېنىتسىن نوبېل ئەدەبىيات مۇكاپاتىغا ئېرىشكەن.","soljénitsin nobél edebiyat mukapatigha érishken."]],"纸板":[["纸板可以用来制作环保包装盒。","قەغەز تاختا مۇھىت ئاسرايدىغان قاچىلاش قۇتىسى ياساشقا ئىشلىتىلىدۇ.","qeghez taxta muhit asraydighan qachilash qutisi yasashqa ishlitilidu."]]};
